import { User, Squad, Player, TrainingSession, AttendanceRecord, UserRole } from '../types';
import { MOCK_USERS, INITIAL_SQUADS, MOCK_PLAYERS } from '../constants';

// Keys
const KEYS = {
  USERS: 'coachpro_users',
  SQUADS: 'coachpro_squads',
  PLAYERS: 'coachpro_players',
  SESSIONS: 'coachpro_sessions',
  ATTENDANCE: 'coachpro_attendance',
  CURRENT_USER: 'coachpro_current_user'
};

// Generic Helpers
const get = <T>(key: string, defaultVal: T): T => {
  const stored = localStorage.getItem(key);
  if (!stored) return defaultVal;
  try {
    return JSON.parse(stored);
  } catch {
    return defaultVal;
  }
};

const set = <T>(key: string, val: T): void => {
  localStorage.setItem(key, JSON.stringify(val));
};

// Data Services
export const storageService = {
  // Users
  getUsers: () => get<User[]>(KEYS.USERS, MOCK_USERS),
  saveUsers: (users: User[]) => set(KEYS.USERS, users),

  // Squads
  getSquads: () => get<Squad[]>(KEYS.SQUADS, INITIAL_SQUADS),
  saveSquads: (squads: Squad[]) => set(KEYS.SQUADS, squads),

  // Players
  getPlayers: () => get<Player[]>(KEYS.PLAYERS, MOCK_PLAYERS),
  savePlayers: (players: Player[]) => set(KEYS.PLAYERS, players),

  // Sessions
  getSessions: () => get<TrainingSession[]>(KEYS.SESSIONS, []),
  saveSessions: (sessions: TrainingSession[]) => set(KEYS.SESSIONS, sessions),

  // Attendance
  getAttendance: () => get<AttendanceRecord[]>(KEYS.ATTENDANCE, []),
  saveAttendance: (records: AttendanceRecord[]) => set(KEYS.ATTENDANCE, records),

  // Auth (Simplified)
  login: (email: string): User | null => {
    const users = get<User[]>(KEYS.USERS, MOCK_USERS);
    const user = users.find(u => u.email === email);
    if (user) {
      localStorage.setItem(KEYS.CURRENT_USER, JSON.stringify(user));
      return user;
    }
    return null;
  },
  logout: () => localStorage.removeItem(KEYS.CURRENT_USER),
  getCurrentUser: (): User | null => get<User | null>(KEYS.CURRENT_USER, null)
};

import { GoogleGenAI } from "@google/genai";
import { Squad } from "../types";

// Note: In a real app, API Key should be securely managed.
// For this demo, we assume process.env.API_KEY is available.
const apiKey = process.env.API_KEY || ''; 

const ai = new GoogleGenAI({ apiKey });

export const generateTrainingPlan = async (
  squad: Squad, 
  focusArea: string, 
  durationMinutes: number,
  playerCount: number
): Promise<string> => {
  if (!apiKey) {
    return "API Key não configurada. Por favor configure a chave da API para usar o assistente.";
  }

  const prompt = `
    Como treinador de futebol profissional, crie um plano de treino detalhado para o escalão ${squad.name}.

    Detalhes:
    - Foco do treino: ${focusArea}
    - Duração: ${durationMinutes} minutos
    - Número de jogadores: ${playerCount}

    O plano deve incluir:
    1. Aquecimento (com tempo)
    2. Exercícios principais (descrição, objetivos e tempo)
    3. Retorno à calma

    Formate a resposta em Markdown limpo e organizado, em Português de Portugal.
    Seja prático e direto.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    return response.text || "Não foi possível gerar o plano de treino.";
  } catch (error) {
    console.error("Erro ao gerar plano:", error);
    return "Ocorreu um erro ao contactar a IA. Verifique a sua ligação ou a chave API.";
  }
};

