import React, { useState, useEffect, useMemo } from 'react';
import { 
  User, Squad, Player, TrainingSession, AttendanceRecord, ViewState, UserRole, AttendanceStatus 
} from './types';
import { storageService } from './services/storageService';
import { generateTrainingPlan } from './services/geminiService';
import Layout from './components/Layout';
import PlayerForm from './components/PlayerForm';
import { 
  Plus, Search, Filter, Trash2, Edit2, Check, X as XIcon, AlertCircle, Clock, Save, BrainCircuit, UserPlus, Shield
} from 'lucide-react';

const App: React.FC = () => {
  // Global State
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<ViewState>('DASHBOARD');
  const [isLoading, setIsLoading] = useState(false);

  // Data State
  const [users, setUsers] = useState<User[]>([]);
  const [squads, setSquads] = useState<Squad[]>([]);
  const [players, setPlayers] = useState<Player[]>([]);
  const [sessions, setSessions] = useState<TrainingSession[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);

  // UI State
  const [isLoginView, setIsLoginView] = useState(true);
  const [loginEmail, setLoginEmail] = useState('admin@club.com');
  const [editingPlayer, setEditingPlayer] = useState<Player | null | undefined>(undefined); // undefined = list mode, null = new, obj = edit
  const [selectedSquadFilter, setSelectedSquadFilter] = useState<string>('all');

  // Training/Attendance UI State
  const [isCreatingSession, setIsCreatingSession] = useState(false);
  const [newSessionData, setNewSessionData] = useState<Partial<TrainingSession>>({});
  const [selectedSessionId, setSelectedSessionId] = useState<string | null>(null);

  // AI State
  const [aiPromptData, setAiPromptData] = useState({ focus: '', duration: 90, squadId: '' });
  const [aiResponse, setAiResponse] = useState<string>('');

  // Initial Load
  useEffect(() => {
    const user = storageService.getCurrentUser();
    if (user) {
      setCurrentUser(user);
      setIsLoginView(false);
      loadData();
    }
  }, []);

  const loadData = () => {
    setUsers(storageService.getUsers());
    setSquads(storageService.getSquads());
    setPlayers(storageService.getPlayers());
    setSessions(storageService.getSessions());
    setAttendance(storageService.getAttendance());
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const user = storageService.login(loginEmail);
    if (user) {
      setCurrentUser(user);
      setIsLoginView(false);
      loadData();
    } else {
      alert("Utilizador não encontrado (Use: admin@club.com ou coach@club.com)");
    }
  };

  const handleLogout = () => {
    storageService.logout();
    setCurrentUser(null);
    setIsLoginView(true);
  };

  // --- Logic for Players ---
  const savePlayer = (player: Player) => {
    let updatedPlayers;
    if (players.find(p => p.id === player.id)) {
      updatedPlayers = players.map(p => p.id === player.id ? player : p);
    } else {
      updatedPlayers = [...players, player];
    }
    setPlayers(updatedPlayers);
    storageService.savePlayers(updatedPlayers);
    setEditingPlayer(undefined);
  };

  const deletePlayer = (id: string) => {
    if (confirm("Tem a certeza que deseja eliminar este atleta?")) {
      const updated = players.filter(p => p.id !== id);
      setPlayers(updated);
      storageService.savePlayers(updated);
    }
  };

  const filteredPlayers = useMemo(() => {
    return selectedSquadFilter === 'all' 
      ? players 
      : players.filter(p => p.squadId === selectedSquadFilter);
  }, [players, selectedSquadFilter]);


  // --- Logic for Training ---
  const createSession = () => {
    if (!newSessionData.date || !newSessionData.squadId) return;
    const session: TrainingSession = {
      id: crypto.randomUUID(),
      date: newSessionData.date!,
      squadId: newSessionData.squadId!,
      time: newSessionData.time || '19:00',
      description: newSessionData.description || 'Treino Regular'
    };
    const updatedSessions = [...sessions, session];
    setSessions(updatedSessions);
    storageService.saveSessions(updatedSessions);
    setIsCreatingSession(false);
    setNewSessionData({});
  };

  const toggleAttendance = (playerId: string, sessionId: string, status: AttendanceStatus) => {
    // Find existing
    const existingIndex = attendance.findIndex(a => a.playerId === playerId && a.sessionId === sessionId);
    let newAttendance = [...attendance];

    if (existingIndex >= 0) {
      if (newAttendance[existingIndex].status === status) {
        // Toggle off if clicking same
        newAttendance.splice(existingIndex, 1); 
      } else {
        // Update status
        newAttendance[existingIndex].status = status;
      }
    } else {
      // Create new
      newAttendance.push({ id: crypto.randomUUID(), playerId, sessionId, status });
    }
    setAttendance(newAttendance);
    storageService.saveAttendance(newAttendance);
  };

  const getAttendanceStatus = (playerId: string, sessionId: string) => {
    return attendance.find(a => a.playerId === playerId && a.sessionId === sessionId)?.status;
  };

  // --- Logic for AI ---
  const handleAiGenerate = async () => {
    setIsLoading(true);
    setAiResponse('');
    const squad = squads.find(s => s.id === aiPromptData.squadId);
    if (!squad) {
      alert("Selecione um escalão.");
      setIsLoading(false);
      return;
    }
    const playerCount = players.filter(p => p.squadId === squad.id).length;

    const plan = await generateTrainingPlan(squad, aiPromptData.focus, aiPromptData.duration, playerCount);
    setAiResponse(plan);
    setIsLoading(false);
  };

  // --- Logic for Admin ---
  const [newUser, setNewUser] = useState<Partial<User>>({ role: UserRole.STAFF, name: '', email: '' });
  const addUser = () => {
    if (!newUser.name || !newUser.email) return;
    const u: User = {
      id: crypto.randomUUID(),
      name: newUser.name!,
      email: newUser.email!,
      role: newUser.role || UserRole.STAFF,
      password: '123'
    };
    const updated = [...users, u];
    setUsers(updated);
    storageService.saveUsers(updated);
    setNewUser({ role: UserRole.STAFF, name: '', email: '' });
  };

  const [newSquadName, setNewSquadName] = useState('');
  const addSquad = () => {
    if(!newSquadName) return;
    const s: Squad = { id: crypto.randomUUID(), name: newSquadName };
    const updated = [...squads, s];
    setSquads(updated);
    storageService.saveSquads(updated);
    setNewSquadName('');
  }

  // --- Render Functions ---

  if (isLoginView) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
        <div className="bg-white rounded-2xl p-8 max-w-md w-full shadow-2xl">
          <div className="flex justify-center mb-6">
             <div className="bg-emerald-600 p-3 rounded-xl">
               <Shield className="w-8 h-8 text-white" />
             </div>
          </div>
          <h1 className="text-2xl font-bold text-center text-slate-800 mb-2">CoachPro Manager</h1>
          <p className="text-center text-slate-500 mb-8">Gestão Profissional de Futebol</p>
          <form onSubmit={handleLogin} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Email</label>
              <input 
                type="email" 
                className="w-full p-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none"
                value={loginEmail}
                onChange={(e) => setLoginEmail(e.target.value)}
                placeholder="admin@club.com"
              />
            </div>
            <button className="w-full py-3 bg-emerald-600 text-white font-bold rounded-lg hover:bg-emerald-700 transition shadow-lg">
              Entrar
            </button>
            <div className="text-xs text-center text-slate-400 mt-4">
              Demo: admin@club.com | coach@club.com
            </div>
          </form>
        </div>
      </div>
    );
  }

  return (
    <Layout user={currentUser!} currentView={currentView} onNavigate={setCurrentView} onLogout={handleLogout}>

      {/* DASHBOARD VIEW */}
      {currentView === 'DASHBOARD' && (
        <div className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-slate-500 text-sm font-medium">Total Atletas</h3>
                <div className="p-2 bg-blue-50 text-blue-600 rounded-lg"><Users className="w-5 h-5"/></div>
              </div>
              <p className="text-3xl font-bold text-slate-800">{players.length}</p>
            </div>
            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-slate-500 text-sm font-medium">Treinos Realizados</h3>
                <div className="p-2 bg-emerald-50 text-emerald-600 rounded-lg"><Check className="w-5 h-5"/></div>
              </div>
              <p className="text-3xl font-bold text-slate-800">{sessions.length}</p>
            </div>
            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-slate-500 text-sm font-medium">Escalões Ativos</h3>
                <div className="p-2 bg-purple-50 text-purple-600 rounded-lg"><Filter className="w-5 h-5"/></div>
              </div>
              <p className="text-3xl font-bold text-slate-800">{squads.length}</p>
            </div>
          </div>

          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
             <h3 className="text-lg font-bold text-slate-800 mb-4">Próximos Treinos</h3>
             {sessions.length === 0 ? (
               <p className="text-slate-500 italic">Sem treinos agendados.</p>
             ) : (
               <div className="space-y-3">
                 {sessions.slice(-3).map(s => (
                   <div key={s.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-lg border border-slate-100">
                      <div>
                        <div className="font-semibold text-slate-800">{squads.find(sq => sq.id === s.squadId)?.name}</div>
                        <div className="text-sm text-slate-500">{s.date} às {s.time}</div>
                      </div>
                      <div className="text-sm px-3 py-1 bg-white rounded border border-slate-200 text-slate-600">
                        {s.description}
                      </div>
                   </div>
                 ))}
               </div>
             )}
          </div>
        </div>
      )}

      {/* PLAYERS VIEW */}
      {currentView === 'PLAYERS' && (
        <>
          {editingPlayer !== undefined ? (
            <PlayerForm 
              player={editingPlayer} 
              squads={squads} 
              onSave={savePlayer} 
              onCancel={() => setEditingPlayer(undefined)} 
            />
          ) : (
            <div className="space-y-6">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                  <input placeholder="Procurar atleta..." className="pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-emerald-500 w-full md:w-64" />
                </div>
                <div className="flex items-center gap-2">
                  <select 
                    value={selectedSquadFilter}
                    onChange={(e) => setSelectedSquadFilter(e.target.value)}
                    className="p-2 border border-slate-300 rounded-lg bg-white"
                  >
                    <option value="all">Todos os Escalões</option>
                    {squads.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                  </select>
                  <button 
                    onClick={() => setEditingPlayer(null)}
                    className="flex items-center px-4 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 transition shadow-sm"
                  >
                    <Plus className="w-4 h-4 mr-2" />
                    Novo Atleta
                  </button>
                </div>
              </div>

              <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50 border-b border-slate-200">
                      <tr>
                        <th className="p-4 font-semibold text-slate-600 text-sm">Nome</th>
                        <th className="p-4 font-semibold text-slate-600 text-sm">Escalão</th>
                        <th className="p-4 font-semibold text-slate-600 text-sm">Camisola</th>
                        <th className="p-4 font-semibold text-slate-600 text-sm hidden md:table-cell">Equipamento</th>
                        <th className="p-4 font-semibold text-slate-600 text-sm text-right">Ações</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {filteredPlayers.map(player => (
                        <tr key={player.id} className="hover:bg-slate-50 transition">
                          <td className="p-4">
                            <div className="font-medium text-slate-900">{player.name}</div>
                            <div className="text-xs text-slate-500">{player.jerseyName}</div>
                          </td>
                          <td className="p-4">
                            <span className="px-2 py-1 bg-emerald-50 text-emerald-700 rounded text-xs font-semibold">
                              {squads.find(s => s.id === player.squadId)?.name}
                            </span>
                          </td>
                          <td className="p-4 text-slate-600">#{player.jerseyNumber}</td>
                          <td className="p-4 text-slate-600 text-sm hidden md:table-cell">
                            Kit: {player.kitSize} | FT: {player.tracksuitSize}
                          </td>
                          <td className="p-4 text-right">
                            <button onClick={() => setEditingPlayer(player)} className="p-1 text-slate-400 hover:text-blue-600 transition"><Edit2 className="w-4 h-4"/></button>
                            <button onClick={() => deletePlayer(player.id)} className="p-1 text-slate-400 hover:text-red-600 transition ml-2"><Trash2 className="w-4 h-4"/></button>
                          </td>
                        </tr>
                      ))}
                      {filteredPlayers.length === 0 && (
                        <tr>
                          <td colSpan={5} className="p-8 text-center text-slate-500">Nenhum atleta encontrado.</td>
                        </tr>
                      )}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}
        </>
      )}

      {/* TRAINING & ATTENDANCE VIEW */}
      {currentView === 'TRAINING' && (
        <div className="space-y-6">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* List of Sessions */}
            <div className="lg:col-span-1 space-y-4">
              <div className="flex justify-between items-center">
                 <h2 className="text-lg font-bold text-slate-800">Sessões</h2>
                 <button 
                  onClick={() => setIsCreatingSession(!isCreatingSession)}
                  className="p-2 bg-emerald-100 text-emerald-700 rounded-lg hover:bg-emerald-200"
                 >
                   <Plus className="w-5 h-5" />
                 </button>
              </div>

              {isCreatingSession && (
                <div className="bg-white p-4 rounded-lg shadow border border-emerald-100 mb-4 animate-in fade-in slide-in-from-top-2">
                   <div className="space-y-3">
                     <input type="date" className="w-full p-2 border rounded" onChange={e => setNewSessionData({...newSessionData, date: e.target.value})} />
                     <input type="time" className="w-full p-2 border rounded" defaultValue="19:00" onChange={e => setNewSessionData({...newSessionData, time: e.target.value})} />
                     <select className="w-full p-2 border rounded" onChange={e => setNewSessionData({...newSessionData, squadId: e.target.value})}>
                       <option value="">Escalão...</option>
                       {squads.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                     </select>
                     <input placeholder="Descrição..." className="w-full p-2 border rounded" onChange={e => setNewSessionData({...newSessionData, description: e.target.value})} />
                     <button onClick={createSession} className="w-full py-2 bg-emerald-600 text-white rounded hover:bg-emerald-700">Criar Treino</button>
                   </div>
                </div>
              )}

              <div className="space-y-2 h-[500px] overflow-y-auto">
                {sessions.sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()).map(session => (
                  <div 
                    key={session.id}
                    onClick={() => setSelectedSessionId(session.id)}
                    className={`p-4 rounded-lg cursor-pointer transition border ${
                      selectedSessionId === session.id 
                        ? 'bg-emerald-600 text-white border-emerald-600 shadow-md' 
                        : 'bg-white hover:bg-slate-50 border-slate-200 text-slate-700'
                    }`}
                  >
                    <div className="font-bold flex justify-between">
                      <span>{session.date}</span>
                      <span className={`text-xs px-2 py-0.5 rounded ${selectedSessionId === session.id ? 'bg-emerald-500' : 'bg-slate-100 text-slate-500'}`}>
                        {squads.find(s => s.id === session.squadId)?.name}
                      </span>
                    </div>
                    <div className="text-sm mt-1 opacity-90">{session.time} - {session.description}</div>
                  </div>
                ))}
              </div>
            </div>

            {/* Attendance Sheet */}
            <div className="lg:col-span-2">
               {selectedSessionId ? (
                 <div className="bg-white rounded-xl shadow-sm border border-slate-200 h-full flex flex-col">
                   <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-xl">
                      <h3 className="font-bold text-slate-700 flex items-center">
                        <UserCircle className="w-5 h-5 mr-2 text-emerald-600" />
                        Registo de Presenças
                      </h3>
                      <div className="text-xs text-slate-500">
                        {sessions.find(s => s.id === selectedSessionId)?.date}
                      </div>
                   </div>

                   <div className="p-4 overflow-y-auto flex-1">
                      {players
                        .filter(p => p.squadId === sessions.find(s => s.id === selectedSessionId)?.squadId)
                        .map(player => {
                          const status = getAttendanceStatus(player.id, selectedSessionId);
                          return (
                            <div key={player.id} className="flex items-center justify-between py-3 border-b border-slate-50 last:border-0 hover:bg-slate-50 px-2 rounded">
                               <div className="flex items-center">
                                 <div className="w-8 h-8 rounded-full bg-slate-200 flex items-center justify-center text-xs font-bold text-slate-600 mr-3">
                                   {player.jerseyNumber}
                                 </div>
                                 <div>
                                   <div className="font-medium text-slate-800">{player.name}</div>
                                 </div>
                               </div>
                               <div className="flex space-x-1">
                                  {[
                                    { s: AttendanceStatus.PRESENT, icon: Check, color: 'bg-emerald-100 text-emerald-700 hover:bg-emerald-200', active: 'bg-emerald-600 text-white' },
                                    { s: AttendanceStatus.ABSENT, icon: XIcon, color: 'bg-red-100 text-red-700 hover:bg-red-200', active: 'bg-red-600 text-white' },
                                    { s: AttendanceStatus.LATE, icon: Clock, color: 'bg-yellow-100 text-yellow-700 hover:bg-yellow-200', active: 'bg-yellow-600 text-white' },
                                    { s: AttendanceStatus.INJURED, icon: AlertCircle, color: 'bg-orange-100 text-orange-700 hover:bg-orange-200', active: 'bg-orange-600 text-white' },
                                  ].map((opt) => (
                                    <button
                                      key={opt.s}
                                      onClick={() => toggleAttendance(player.id, selectedSessionId, opt.s)}
                                      className={`p-2 rounded-lg transition ${status === opt.s ? opt.active : opt.color}`}
                                      title={opt.s}
                                    >
                                      <opt.icon className="w-4 h-4" />
                                    </button>
                                  ))}
                               </div>
                            </div>
                          );
                        })}
                   </div>
                 </div>
               ) : (
                 <div className="h-full flex flex-col items-center justify-center text-slate-400 border-2 border-dashed border-slate-200 rounded-xl bg-slate-50">
                    <CalendarDays className="w-12 h-12 mb-2 opacity-50" />
                    <p>Selecione um treino para gerir presenças</p>
                 </div>
               )}
            </div>
          </div>
        </div>
      )}

      {/* AI ASSISTANT VIEW */}
      {currentView === 'AI_ASSISTANT' && (
        <div className="max-w-4xl mx-auto space-y-6">
           <div className="bg-gradient-to-r from-emerald-600 to-teal-600 p-8 rounded-2xl shadow-lg text-white">
              <h2 className="text-2xl font-bold flex items-center mb-2">
                <BrainCircuit className="w-8 h-8 mr-3" />
                Assistente de Treino IA
              </h2>
              <p className="opacity-90 max-w-xl">
                Gere planos de treino completos adaptados ao seu escalão, número de jogadores e foco técnico/tático em segundos.
              </p>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="md:col-span-1 space-y-4">
                 <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
                    <h3 className="font-semibold text-slate-800 mb-4">Configuração</h3>

                    <div className="space-y-4">
                       <div>
                         <label className="block text-sm font-medium text-slate-600 mb-1">Escalão</label>
                         <select 
                            className="w-full p-2 border rounded-lg"
                            value={aiPromptData.squadId}
                            onChange={(e) => setAiPromptData({...aiPromptData, squadId: e.target.value})}
                         >
                           <option value="">Selecione...</option>
                           {squads.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                         </select>
                       </div>

                       <div>
                         <label className="block text-sm font-medium text-slate-600 mb-1">Foco do Treino</label>
                         <input 
                            placeholder="Ex: Finalização, Posse de bola..."
                            className="w-full p-2 border rounded-lg"
                            value={aiPromptData.focus}
                            onChange={(e) => setAiPromptData({...aiPromptData, focus: e.target.value})}
                         />
                       </div>

                       <div>
                         <label className="block text-sm font-medium text-slate-600 mb-1">Duração (Min)</label>
                         <input 
                            type="number"
                            className="w-full p-2 border rounded-lg"
                            value={aiPromptData.duration}
                            onChange={(e) => setAiPromptData({...aiPromptData, duration: parseInt(e.target.value)})}
                         />
                       </div>

                       <button 
                         onClick={handleAiGenerate}
                         disabled={isLoading}
                         className="w-full py-3 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 transition flex justify-center items-center font-medium disabled:opacity-50"
                       >
                         {isLoading ? 'A Gerar...' : 'Gerar Plano'}
                       </button>
                    </div>
                 </div>
              </div>

              <div className="md:col-span-2">
                <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 min-h-[400px]">
                   {aiResponse ? (
                     <div className="prose prose-emerald max-w-none">
                       <pre className="whitespace-pre-wrap font-sans text-slate-700">{aiResponse}</pre>
                     </div>
                   ) : (
                     <div className="h-full flex flex-col items-center justify-center text-slate-400">
                       <BrainCircuit className="w-16 h-16 mb-4 opacity-20" />
                       <p>Configure e clique em "Gerar Plano" para ver a sugestão da IA.</p>
                     </div>
                   )}
                </div>
              </div>
           </div>
        </div>
      )}

      {/* ADMIN VIEW */}
      {currentView === 'ADMIN' && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
           {/* Squad Management */}
           <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
              <h3 className="text-xl font-bold text-slate-800 mb-6 flex items-center">
                <Filter className="w-5 h-5 mr-2" /> Gestão de Escalões
              </h3>

              <div className="flex gap-2 mb-6">
                <input 
                  placeholder="Novo escalão (ex: Sub-13)..." 
                  className="flex-1 p-2 border border-slate-300 rounded-lg"
                  value={newSquadName}
                  onChange={(e) => setNewSquadName(e.target.value)}
                />
                <button onClick={addSquad} className="px-4 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700"><Plus/></button>
              </div>

              <ul className="space-y-2">
                {squads.map(s => (
                  <li key={s.id} className="flex justify-between p-3 bg-slate-50 rounded-lg border border-slate-100 items-center">
                    <span className="font-medium text-slate-700">{s.name}</span>
                    <span className="text-xs bg-slate-200 px-2 py-1 rounded text-slate-500">{players.filter(p => p.squadId === s.id).length} atletas</span>
                  </li>
                ))}
              </ul>
           </div>

           {/* User Management */}
           <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
              <h3 className="text-xl font-bold text-slate-800 mb-6 flex items-center">
                <UserPlus className="w-5 h-5 mr-2" /> Gestão de Utilizadores
              </h3>

              <div className="space-y-3 mb-6 bg-slate-50 p-4 rounded-lg border border-slate-100">
                <h4 className="text-sm font-bold text-slate-500 uppercase">Adicionar Novo</h4>
                <input 
                  placeholder="Nome" 
                  className="w-full p-2 border border-slate-300 rounded"
                  value={newUser.name}
                  onChange={e => setNewUser({...newUser, name: e.target.value})}
                />
                <input 
                  placeholder="Email" 
                  className="w-full p-2 border border-slate-300 rounded"
                  value={newUser.email}
                  onChange={e => setNewUser({...newUser, email: e.target.value})}
                />
                <select 
                  className="w-full p-2 border border-slate-300 rounded"
                  value={newUser.role}
                  onChange={e => setNewUser({...newUser, role: e.target.value as UserRole})}
                >
                  <option value={UserRole.ADMIN}>Administrador</option>
                  <option value={UserRole.COACH}>Treinador</option>
                  <option value={UserRole.STAFF}>Staff</option>
                </select>
                <button onClick={addUser} className="w-full py-2 bg-slate-800 text-white rounded hover:bg-slate-900 font-medium">Adicionar Utilizador</button>
              </div>

              <div className="space-y-2">
                 {users.map(u => (
                   <div key={u.id} className="p-3 border rounded-lg flex justify-between items-center">
                      <div>
                        <div className="font-bold text-slate-800">{u.name}</div>
                        <div className="text-xs text-slate-500">{u.email}</div>
                      </div>
                      <span className="px-2 py-1 bg-slate-100 text-slate-600 text-xs font-semibold rounded">{u.role}</span>
                   </div>
                 ))}
              </div>
           </div>
        </div>
      )}

    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  User, Squad, Player, TrainingSession, AttendanceRecord, ViewState, UserRole, AttendanceStatus 
} from './types';
import { storageService } from './services/storageService';
import { generateTrainingPlan } from './services/geminiService';
import Layout from './components/Layout';
import PlayerForm from './components/PlayerForm';
import { 
  Plus, Search, Filter, Trash2, Edit2, Check, X as XIcon, AlertCircle, Clock, Save, BrainCircuit, UserPlus, Shield, Users, UserCircle, CalendarDays
} from 'lucide-react';

const App: React.FC = () => {
  // Global State
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<ViewState>('DASHBOARD');
  const [isLoading, setIsLoading] = useState(false);

  // Data State
  const [users, setUsers] = useState<User[]>([]);
  const [squads, setSquads] = useState<Squad[]>([]);
  const [players, setPlayers] = useState<Player[]>([]);
  const [sessions, setSessions] = useState<TrainingSession[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);

  // UI State
  const [isLoginView, setIsLoginView] = useState(true);
  const [loginEmail, setLoginEmail] = useState('admin@club.com');
  const [editingPlayer, setEditingPlayer] = useState<Player | null | undefined>(undefined); // undefined = list mode, null = new, obj = edit
  const [selectedSquadFilter, setSelectedSquadFilter] = useState<string>('all');

  // Training/Attendance UI State
  const [isCreatingSession, setIsCreatingSession] = useState(false);
  const [newSessionData, setNewSessionData] = useState<Partial<TrainingSession>>({});
  const [selectedSessionId, setSelectedSessionId] = useState<string | null>(null);

  // AI State
  const [aiPromptData, setAiPromptData] = useState({ focus: '', duration: 90, squadId: '' });
  const [aiResponse, setAiResponse] = useState<string>('');

  // Initial Load
  useEffect(() => {
    const user = storageService.getCurrentUser();
    if (user) {
      setCurrentUser(user);
      setIsLoginView(false);
      loadData();
    }
  }, []);

  const loadData = () => {
    setUsers(storageService.getUsers());
    setSquads(storageService.getSquads());
    setPlayers(storageService.getPlayers());
    setSessions(storageService.getSessions());
    setAttendance(storageService.getAttendance());
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const user = storageService.login(loginEmail);
    if (user) {
      setCurrentUser(user);
      setIsLoginView(false);
      loadData();
    } else {
      alert("Utilizador não encontrado (Use: admin@club.com ou coach@club.com)");
    }
  };

  const handleLogout = () => {
    storageService.logout();
    setCurrentUser(null);
    setIsLoginView(true);
  };

  // --- Logic for Players ---
  const savePlayer = (player: Player) => {
    let updatedPlayers;
    if (players.find(p => p.id === player.id)) {
      updatedPlayers = players.map(p => p.id === player.id ? player : p);
    } else {
      updatedPlayers = [...players, player];
    }
    setPlayers(updatedPlayers);
    storageService.savePlayers(updatedPlayers);
    setEditingPlayer(undefined);
  };

  const deletePlayer = (id: string) => {
    if (confirm("Tem a certeza que deseja eliminar este atleta?")) {
      const updated = players.filter(p => p.id !== id);
      setPlayers(updated);
      storageService.savePlayers(updated);
    }
  };

  const filteredPlayers = useMemo(() => {
    return selectedSquadFilter === 'all' 
      ? players 
      : players.filter(p => p.squadId === selectedSquadFilter);
  }, [players, selectedSquadFilter]);


  // --- Logic for Training ---
  const createSession = () => {
    if (!newSessionData.date || !newSessionData.squadId) return;
    const session: TrainingSession = {
      id: crypto.randomUUID(),
      date: newSessionData.date!,
      squadId: newSessionData.squadId!,
      time: newSessionData.time || '19:00',
      description: newSessionData.description || 'Treino Regular'
    };
    const updatedSessions = [...sessions, session];
    setSessions(updatedSessions);
    storageService.saveSessions(updatedSessions);
    setIsCreatingSession(false);
    setNewSessionData({});
  };

  const toggleAttendance = (playerId: string, sessionId: string, status: AttendanceStatus) => {
    // Find existing
    const existingIndex = attendance.findIndex(a => a.playerId === playerId && a.sessionId === sessionId);
    let newAttendance = [...attendance];

    if (existingIndex >= 0) {
      if (newAttendance[existingIndex].status === status) {
        // Toggle off if clicking same
        newAttendance.splice(existingIndex, 1); 
      } else {
        // Update status
        newAttendance[existingIndex].status = status;
      }
    } else {
      // Create new
      newAttendance.push({ id: crypto.randomUUID(), playerId, sessionId, status });
    }
    setAttendance(newAttendance);
    storageService.saveAttendance(newAttendance);
  };

  const getAttendanceStatus = (playerId: string, sessionId: string) => {
    return attendance.find(a => a.playerId === playerId && a.sessionId === sessionId)?.status;
  };

  // --- Logic for AI ---
  const handleAiGenerate = async () => {
    setIsLoading(true);
    setAiResponse('');
    const squad = squads.find(s => s.id === aiPromptData.squadId);
    if (!squad) {
      alert("Selecione um escalão.");
      setIsLoading(false);
      return;
    }
    const playerCount = players.filter(p => p.squadId === squad.id).length;

    const plan = await generateTrainingPlan(squad, aiPromptData.focus, aiPromptData.duration, playerCount);
    setAiResponse(plan);
    setIsLoading(false);
  };

  // --- Logic for Admin ---
  const [newUser, setNewUser] = useState<Partial<User>>({ role: UserRole.STAFF, name: '', email: '' });
  const addUser = () => {
    if (!newUser.name || !newUser.email) return;
    const u: User = {
      id: crypto.randomUUID(),
      name: newUser.name!,
      email: newUser.email!,
      role: newUser.role || UserRole.STAFF,
      password: '123'
    };
    const updated = [...users, u];
    setUsers(updated);
    storageService.saveUsers(updated);
    setNewUser({ role: UserRole.STAFF, name: '', email: '' });
  };

  const [newSquadName, setNewSquadName] = useState('');
  const addSquad = () => {
    if(!newSquadName) return;
    const s: Squad = { id: crypto.randomUUID(), name: newSquadName };
    const updated = [...squads, s];
    setSquads(updated);
    storageService.saveSquads(updated);
    setNewSquadName('');
  }

  // --- Render Functions ---

  if (isLoginView) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
        <div className="bg-white rounded-2xl p-8 max-w-md w-full shadow-2xl">
          <div className="flex justify-center mb-6">
             <div className="bg-emerald-600 p-3 rounded-xl">
               <Shield className="w-8 h-8 text-white" />
             </div>
          </div>
          <h1 className="text-2xl font-bold text-center text-slate-800 mb-2">CoachPro Manager</h1>
          <p className="text-center text-slate-500 mb-8">Gestão Profissional de Futebol</p>
          <form onSubmit={handleLogin} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Email</label>
              <input 
                type="email" 
                className="w-full p-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none"
                value={loginEmail}
                onChange={(e) => setLoginEmail(e.target.value)}
                placeholder="admin@club.com"
              />
            </div>
            <button className="w-full py-3 bg-emerald-600 text-white font-bold rounded-lg hover:bg-emerald-700 transition shadow-lg">
              Entrar
            </button>
            <div className="text-xs text-center text-slate-400 mt-4">
              Demo: admin@club.com | coach@club.com
            </div>
          </form>
        </div>
      </div>
    );
  }

  return (
    <Layout user={currentUser!} currentView={currentView} onNavigate={setCurrentView} onLogout={handleLogout}>

      {/* DASHBOARD VIEW */}
      {currentView === 'DASHBOARD' && (
        <div className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-slate-500 text-sm font-medium">Total Atletas</h3>
                <div className="p-2 bg-blue-50 text-blue-600 rounded-lg"><Users className="w-5 h-5"/></div>
              </div>
              <p className="text-3xl font-bold text-slate-800">{players.length}</p>
            </div>
            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-slate-500 text-sm font-medium">Treinos Realizados</h3>
                <div className="p-2 bg-emerald-50 text-emerald-600 rounded-lg"><Check className="w-5 h-5"/></div>
              </div>
              <p className="text-3xl font-bold text-slate-800">{sessions.length}</p>
            </div>
            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-slate-500 text-sm font-medium">Escalões Ativos</h3>
                <div className="p-2 bg-purple-50 text-purple-600 rounded-lg"><Filter className="w-5 h-5"/></div>
              </div>
              <p className="text-3xl font-bold text-slate-800">{squads.length}</p>
            </div>
          </div>

          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
             <h3 className="text-lg font-bold text-slate-800 mb-4">Próximos Treinos</h3>
