import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { Match, Squad, Player } from '../types';
import { CLUB_NAME, CLUB_LOGO_URL } from '../constants';

const getDataUrl = (url: string): Promise<string> => {
  return new Promise((resolve) => {
    const img = new Image();
    img.crossOrigin = 'Anonymous';
    img.src = url;
    img.onload = () => {
      const canvas = document.createElement('canvas');
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(img, 0, 0);
        try {
          resolve(canvas.toDataURL('image/png'));
        } catch (e) {
           console.warn("CORS blocked canvas export", e);
           resolve('');
        }
      } else {
        resolve('');
      }
    };
    img.onerror = () => {
      console.warn("Could not load logo for PDF");
      resolve('');
    };
  });
};

export const generateConvocationPDF = async (
  match: Match, 
  squad: Squad, 
  players: Player[]
) => {
  const doc = new jsPDF();

  // -- Colors --
  const primaryColor = [16, 185, 129]; // Emerald 500
  const darkColor = [30, 41, 59]; // Slate 800

  let headerOffset = 0;

  // -- Load Logo --
  const logoData = await getDataUrl(CLUB_LOGO_URL);
  if (logoData) {
    // Add logo to top left
    doc.addImage(logoData, 'PNG', 14, 15, 20, 20); // x, y, w, h
    headerOffset = 25; // Push text to the right
  }

  // -- Header --
  doc.setFontSize(22);
  doc.setTextColor(primaryColor[0], primaryColor[1], primaryColor[2]);
  doc.text(CLUB_NAME, 14 + headerOffset, 22);

  doc.setFontSize(12);
  doc.setTextColor(100, 100, 100);
  doc.text("Gestão de Equipas", 14 + headerOffset, 28);

  // -- Match Title --
  doc.setFontSize(18);
  doc.setTextColor(darkColor[0], darkColor[1], darkColor[2]);
  doc.text(`CONVOCATÓRIA - ${squad.name.toUpperCase()}`, 14, 45);

  // -- Match Details --
  doc.setFontSize(11);
  doc.setTextColor(0, 0, 0);

  let detailsY = 55;
  doc.setFont("helvetica", "bold");
  doc.text("Adversário:", 14, detailsY);
  doc.setFont("helvetica", "normal");
  doc.text(match.opponent, 40, detailsY);

  doc.setFont("helvetica", "bold");
  doc.text("Data/Hora:", 14, detailsY + 6);
  doc.setFont("helvetica", "normal");
  doc.text(`${match.date} às ${match.time}`, 40, detailsY + 6);

  doc.setFont("helvetica", "bold");
  doc.text("Local:", 14, detailsY + 12);
  doc.setFont("helvetica", "normal");
  doc.text(match.location, 40, detailsY + 12);

  if (match.playerKit || match.goalkeeperKit) {
     detailsY += 6;
     doc.setFont("helvetica", "bold");
     doc.text("Equipamentos:", 14, detailsY + 12);
     doc.setFont("helvetica", "normal");
     let kitText = "";
     if(match.playerKit) kitText += `Jogadores: ${match.playerKit} `;
     if(match.goalkeeperKit) kitText += `| GR: ${match.goalkeeperKit}`;
     doc.text(kitText, 45, detailsY + 12);
     detailsY += 6;
  }

  // -- Players Table --
  // Sort players by jersey number
  const sortedPlayers = [...players].sort((a, b) => Number(a.jerseyNumber) - Number(b.jerseyNumber));

  const tableData = sortedPlayers.map(p => [
    p.jerseyNumber,
    p.name,
    p.jerseyName || '-'
  ]);

  autoTable(doc, {
    startY: detailsY + 20,
    head: [['#', 'Nome Completo', 'Nome Camisola']],
    body: tableData,
    theme: 'grid',
    headStyles: {
      fillColor: [16, 185, 129], // Emerald 500
      textColor: 255,
      fontStyle: 'bold'
    },
    styles: {
      fontSize: 10,
      cellPadding: 3
    },
    alternateRowStyles: {
      fillColor: [240, 253, 244] // Emerald 50
    }
  });

  // -- Notes Section --
  if (match.notes) {
    const finalY = (doc as any).lastAutoTable.finalY + 10;
    doc.setFontSize(10);
    doc.setTextColor(primaryColor[0], primaryColor[1], primaryColor[2]);
    doc.setFont("helvetica", "bold");
    doc.text("OBSERVAÇÕES:", 14, finalY);

    doc.setFontSize(10);
    doc.setTextColor(0, 0, 0);
    doc.setFont("helvetica", "normal");

    // Split text to fit page width
    const splitNotes = doc.splitTextToSize(match.notes, 180);
    doc.text(splitNotes, 14, finalY + 5);
  }

  // -- Footer --
  const pageHeight = doc.internal.pageSize.height;
  doc.setFontSize(8);
  doc.setTextColor(150, 150, 150);
  doc.text(`Documento gerado automaticamente por ${CLUB_NAME} Manager`, 14, pageHeight - 10);

  // -- Save File --
  const filename = `Convocatoria_${squad.name}_vs_${match.opponent.replace(/\s+/g, '_')}.pdf`;
  doc.save(filename);
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  User, Squad, Player, TrainingSession, AttendanceRecord, ViewState, UserRole, AttendanceStatus, Match, MatchData 
} from './types';
import { storageService } from './services/storageService';
import { generateConvocationPDF } from './services/pdfService';
import { CLUB_NAME, CLUB_LOGO_URL, FORMATIONS } from './constants';
import Layout from './components/Layout';
import PlayerForm from './components/PlayerForm';
import { 
  Plus, Search, Filter, Trash2, Edit2, Check, X as XIcon, AlertCircle, Clock, Save, UserPlus, Users, UserCircle, CalendarDays, KeyRound, Flag, Copy, FileDown, Loader2, Play, Pause, Square, Shirt, Shield, ArrowRightLeft
} from 'lucide-react';

const App: React.FC = () => {
  // Global State
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<ViewState>('DASHBOARD');
  const [isLoading, setIsLoading] = useState(false);

  // Data State
  const [users, setUsers] = useState<User[]>([]);
  const [squads, setSquads] = useState<Squad[]>([]);
  const [players, setPlayers] = useState<Player[]>([]);
  const [sessions, setSessions] = useState<TrainingSession[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [matches, setMatches] = useState<Match[]>([]);

  // UI State
  const [isLoginView, setIsLoginView] = useState(true);
  const [selectedLoginUserId, setSelectedLoginUserId] = useState('');

  const [editingPlayer, setEditingPlayer] = useState<Player | null | undefined>(undefined); 
  const [selectedSquadFilter, setSelectedSquadFilter] = useState<string>('all');

  // Training/Attendance UI State
  const [isSessionModalOpen, setIsSessionModalOpen] = useState(false);
  const [editingSession, setEditingSession] = useState<Partial<TrainingSession>>({});
  const [selectedSessionId, setSelectedSessionId] = useState<string | null>(null);

  // Matches UI State
  const [isMatchModalOpen, setIsMatchModalOpen] = useState(false);
  const [editingMatch, setEditingMatch] = useState<Partial<Match>>({});
  const [selectedMatchId, setSelectedMatchId] = useState<string | null>(null);
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);

  // Game Day UI State
  const [activeGameTab, setActiveGameTab] = useState<'LINEUP' | 'TACTICS' | 'LIVE'>('LINEUP');

  // --- TIMER LOGIC ---
  const timerRef = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => {
    // Clear timer on unmount
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, []);

  // Timer Tick
  useEffect(() => {
    if (selectedMatchId && matches.length > 0) {
      const match = matches.find(m => m.id === selectedMatchId);
      if (match?.gameData && (match.gameData.currentPeriod === '1H' || match.gameData.currentPeriod === '2H')) {
          if (!timerRef.current) {
            timerRef.current = setInterval(() => {
                setMatches(prevMatches => {
                    return prevMatches.map(m => {
                        if (m.id === selectedMatchId && m.gameData) {
                             // Increment timer
                             const newTimer = m.gameData.timer + 1;

                             // Update Minutes Played for starters every 60 seconds (approx)
                             // For smoother UI, we just update the simple counter here, 
                             // but calculating real minutes played involves adding 1/60th of a minute
                             const newPlayerMinutes = { ...m.gameData.playerMinutes };
                             if (newTimer % 60 === 0) {
                                 m.gameData.starters.forEach(pid => {
                                     newPlayerMinutes[pid] = (newPlayerMinutes[pid] || 0) + 1;
                                 });
                             }

                             return {
                                 ...m,
                                 gameData: {
                                     ...m.gameData,
                                     timer: newTimer,
                                     playerMinutes: newPlayerMinutes
                                 }
                             };
                        }
                        return m;
                    });
                });
            }, 1000); // Speed up for testing? No, keep real time.
          }
      } else {
          if (timerRef.current) {
              clearInterval(timerRef.current);
              timerRef.current = null;
          }
      }
    }
  }, [selectedMatchId, matches]);


  // Initial Load
  useEffect(() => {
    const user = storageService.getCurrentUser();
    // Load users list for login screen even if not logged in
    const storedUsers = storageService.getUsers();
    setUsers(storedUsers);

    if (user) {
      setCurrentUser(user);
      setIsLoginView(false);
      loadData();
    }
  }, []);

  const loadData = () => {
    setUsers(storageService.getUsers());
    setSquads(storageService.getSquads());
    setPlayers(storageService.getPlayers());
    setSessions(storageService.getSessions());
    setAttendance(storageService.getAttendance());
    setMatches(storageService.getMatches());
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if(!selectedLoginUserId) return;
    const user = users.find(u => u.id === selectedLoginUserId);
    if (user) {
      storageService.login(user.username, user.password || ''); // Simplified login
      setCurrentUser(user);
      setIsLoginView(false);
      loadData();
    }
  };

  const handleLogout = () => {
    storageService.logout();
    setCurrentUser(null);
    setIsLoginView(true);
    setSelectedLoginUserId('');
  };

  // --- Helper: Visible Squads for Current User ---
  const visibleSquads = useMemo(() => {
    if (!currentUser) return [];
    if (currentUser.role === UserRole.ADMIN) return squads;
    if (!currentUser.allowedSquads || currentUser.allowedSquads.length === 0) return [];
    return squads.filter(s => currentUser.allowedSquads?.includes(s.id));
  }, [squads, currentUser]);

  const visiblePlayers = useMemo(() => {
    const squadIds = visibleSquads.map(s => s.id);
    return players.filter(p => squadIds.includes(p.squadId));
  }, [players, visibleSquads]);

  // --- Logic for Players ---
  const savePlayer = (player: Player) => {
    let updatedPlayers;
    if (players.find(p => p.id === player.id)) {
      updatedPlayers = players.map(p => p.id === player.id ? player : p);
    } else {
      updatedPlayers = [...players, player];
    }
    setPlayers(updatedPlayers);
    storageService.savePlayers(updatedPlayers);
    setEditingPlayer(undefined);
  };

  const deletePlayer = (id: string) => {
    if (confirm("Tem a certeza que deseja eliminar este atleta?")) {
      const updated = players.filter(p => p.id !== id);
      setPlayers(updated);
      storageService.savePlayers(updated);
    }
  };

  const filteredPlayers = useMemo(() => {
    let filtered = visiblePlayers;
    if (selectedSquadFilter !== 'all') {
      filtered = filtered.filter(p => p.squadId === selectedSquadFilter);
    }
    return filtered.sort((a,b) => (a.jerseyNumber as number) - (b.jerseyNumber as number));
  }, [visiblePlayers, selectedSquadFilter]);

  const calculateAge = (birthDateStr: string) => {
    if (!birthDateStr) return '-';
    const birth = new Date(birthDateStr);
    const now = new Date();
    let age = now.getFullYear() - birth.getFullYear();
    const m = now.getMonth() - birth.getMonth();
    if (m < 0 || (m === 0 && now.getDate() < birth.getDate())) {
      age--;
    }
    return age;
  };

  const copySquadList = () => {
    if (selectedSquadFilter === 'all') {
        alert("Por favor selecione um escalão específico para exportar a listagem.");
        return;
    }
    const squad = squads.find(s => s.id === selectedSquadFilter);
    let text = `LISTAGEM - ${squad?.name.toUpperCase()}\n\n`;
    filteredPlayers.forEach(p => {
        text += `${p.jerseyNumber}. ${p.name} (${calculateAge(p.birthDate)} anos)\n`;
    });

    navigator.clipboard.writeText(text);
    alert("Listagem copiada para a área de transferência!");
  };

  // --- Logic for Training ---
  const openSessionModal = (session?: TrainingSession) => {
      setEditingSession(session || { date: new Date().toISOString().split('T')[0], time: '19:00', squadId: visibleSquads[0]?.id });
      setIsSessionModalOpen(true);
  }

  const saveSession = () => {
    if (!editingSession.date || !editingSession.squadId) return;

    let updatedSessions = [...sessions];
    if (editingSession.id) {
        // Edit
        updatedSessions = updatedSessions.map(s => s.id === editingSession.id ? { ...s, ...editingSession } as TrainingSession : s);
    } else {
        // Create
        const session: TrainingSession = {
            id: crypto.randomUUID(),
            date: editingSession.date!,
            squadId: editingSession.squadId!,
            time: editingSession.time || '19:00',
            description: editingSession.description || 'Treino'
        };
        updatedSessions.push(session);
    }
    setSessions(updatedSessions);
    storageService.saveSessions(updatedSessions);
    setIsSessionModalOpen(false);
    setEditingSession({});
  };

  const toggleAttendance = (playerId: string, sessionId: string, status: AttendanceStatus) => {
    const existingIndex = attendance.findIndex(a => a.playerId === playerId && a.sessionId === sessionId);
    let newAttendance = [...attendance];
    if (existingIndex >= 0) {
      if (newAttendance[existingIndex].status === status) {
        newAttendance.splice(existingIndex, 1); 
      } else {
        newAttendance[existingIndex].status = status;
      }
    } else {
      newAttendance.push({ id: crypto.randomUUID(), playerId, sessionId, status });
    }
    setAttendance(newAttendance);
    storageService.saveAttendance(newAttendance);
  };

  const getAttendanceStatus = (playerId: string, sessionId: string | null) => {
    if (!sessionId) return undefined;
    const record = attendance.find(a => a.playerId === playerId && a.sessionId === sessionId);
    return record?.status;
  };

  // --- Logic for Matches (Convocatórias & Game Day) ---
  const openMatchModal = (match?: Match) => {
      setEditingMatch(match || { 
          date: new Date().toISOString().split('T')[0], 
          time: '15:00', 
          squadId: visibleSquads[0]?.id,
          location: 'Casa'
      });
      setIsMatchModalOpen(true);
  }

  const saveMatch = () => {
    if (!editingMatch.date || !editingMatch.squadId || !editingMatch.opponent) return;

    let updatedMatches = [...matches];
    if (editingMatch.id) {
        updatedMatches = updatedMatches.map(m => m.id === editingMatch.id ? { ...m, ...editingMatch } as Match : m);
    } else {
        const match: Match = {
            id: crypto.randomUUID(),
            squadId: editingMatch.squadId!,
            date: editingMatch.date!,
            time: editingMatch.time || '15:00',
            opponent: editingMatch.opponent!,
            location: editingMatch.location as 'Casa' | 'Fora' || 'Casa',
            convokedIds: [],
            notes: editingMatch.notes || '',
            playerKit: editingMatch.playerKit,
            goalkeeperKit: editingMatch.goalkeeperKit
        };
        updatedMatches.push(match);
    }
    setMatches(updatedMatches);
    storageService.saveMatches(updatedMatches);
    setIsMatchModalOpen(false);
    setEditingMatch({});
  };

  const toggleConvocation = (matchId: string, playerId: string) => {
    const match = matches.find(m => m.id === matchId);
    if (!match) return;

    let newConvoked = [...match.convokedIds];
    if (newConvoked.includes(playerId)) {
      newConvoked = newConvoked.filter(id => id !== playerId);
      // Also remove from lineups if they exist
      if (match.gameData) {
          updateMatchGameData(matchId, {
              starters: match.gameData.starters.filter(id => id !== playerId),
              substitutes: match.gameData.substitutes.filter(id => id !== playerId)
          });
          return; // Return early because we updated via helper
      }
    } else {
      newConvoked.push(playerId);
    }

    const updatedMatches = matches.map(m => m.id === matchId ? { ...m, convokedIds: newConvoked } : m);
    setMatches(updatedMatches);
    storageService.saveMatches(updatedMatches);
  };

  const updateMatchGameData = (matchId: string, data: Partial<MatchData>) => {
      const updatedMatches = matches.map(m => {
          if (m.id === matchId) {
              const prevData = m.gameData || {
                  starters: [],
                  substitutes: [],
                  formation: '4-3-3 (F11)',
                  events: [],
                  playerMinutes: {},
                  currentPeriod: 'PRE',
                  timer: 0
              };
              return { ...m, gameData: { ...prevData, ...data } };
          }
          return m;
      });
      setMatches(updatedMatches);
      storageService.saveMatches(updatedMatches);
  };

  const moveToStarter = (matchId: string, playerId: string) => {
      const match = matches.find(m => m.id === matchId);
      if (!match) return;
      const currentStarters = match.gameData?.starters || [];
      const currentSubs = match.gameData?.substitutes || [];

      if (!currentStarters.includes(playerId)) {
          updateMatchGameData(matchId, {
              starters: [...currentStarters, playerId],
              substitutes: currentSubs.filter(id => id !== playerId)
          });
      }
  };

  const moveToSub = (matchId: string, playerId: string) => {
      const match = matches.find(m => m.id === matchId);
      if (!match) return;
      const currentStarters = match.gameData?.starters || [];
      const currentSubs = match.gameData?.substitutes || [];

      if (!currentSubs.includes(playerId)) {
          updateMatchGameData(matchId, {
              substitutes: [...currentSubs, playerId],
              starters: currentStarters.filter(id => id !== playerId)
          });
      }
  };

  const handleSubstitution = (matchId: string, playerOutId: string, playerInId: string) => {
     moveToSub(matchId, playerOutId);
     moveToStarter(matchId, playerInId);
     // Log event could be added here
  };

  const setGamePeriod = (matchId: string, period: MatchData['currentPeriod']) => {
      updateMatchGameData(matchId, { currentPeriod: period });
  };

  const formatTime = (seconds: number) => {
      const m = Math.floor(seconds / 60);
      const s = seconds % 60;
      return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  // --- PDF ---
  const downloadConvocationPDF = async (matchId: string) => {
    const match = matches.find(m => m.id === matchId);
    if (!match) return;
    const squad = squads.find(s => s.id === match.squadId);
    const convokedPlayers = players.filter(p => match.convokedIds.includes(p.id));

    if (squad && convokedPlayers.length > 0) {
      setIsGeneratingPdf(true);
      try {
        await generateConvocationPDF(match, squad, convokedPlayers);
      } catch (e) {
        console.error(e);
        alert("Erro ao gerar PDF.");
      } finally {
        setIsGeneratingPdf(false);
      }
    } else {
      alert("É necessário ter atletas convocados para gerar o PDF.");
    }
  };

  const copyConvocation = (matchId: string) => {
    const match = matches.find(m => m.id === matchId);
    if (!match) return;
    const squad = squads.find(s => s.id === match.squadId);
    const convokedPlayers = players.filter(p => match.convokedIds.includes(p.id));

    let text = `CONVOCATÓRIA ${squad?.name.toUpperCase()}\n`;
    text += `Vs: ${match.opponent} (${match.location})\n`;
    text += `Data: ${match.date} ${match.time}\n`;
    if(match.playerKit) text += `Equip: ${match.playerKit}\n`;
    if (match.notes) text += `Obs: ${match.notes}\n`;
    text += `\nATLETAS:\n`;
    convokedPlayers.forEach(p => {
      text += `- ${p.name} (${p.jerseyNumber})\n`;
    });

    navigator.clipboard.writeText(text);
    alert("Convocatória copiada!");
  };

  // --- Logic for Admin ---
  const [newUser, setNewUser] = useState<Partial<User>>({ role: UserRole.STAFF, name: '', username: '', allowedSquads: [] });
  const [newSquadName, setNewSquadName] = useState('');

  const addUser = () => {
    if (!newUser.name || !newUser.username) return;
    const u: User = {
      id: crypto.randomUUID(),
      name: newUser.name!,
      username: newUser.username!,
      role: newUser.role || UserRole.STAFF,
      password: '123',
      allowedSquads: newUser.allowedSquads
    };
    const updated = [...users, u];
    setUsers(updated);
    storageService.saveUsers(updated);
    setNewUser({ role: UserRole.STAFF, name: '', username: '', allowedSquads: [] });
  };

  const deleteUser = (id: string) => {
      if(confirm('Eliminar utilizador?')) {
          const updated = users.filter(u => u.id !== id);
          setUsers(updated);
          storageService.saveUsers(updated);
      }
  }

  const addSquad = () => {
    if(!newSquadName) return;
    const s: Squad = { id: crypto.randomUUID(), name: newSquadName };
    const updated = [...squads, s];
    setSquads(updated);
    storageService.saveSquads(updated);
    setNewSquadName('');
  }

  const deleteSquad = (id: string) => {
      if(confirm('Eliminar escalão? Todos os dados associados serão perdidos visualmente.')) {
          const updated = squads.filter(s => s.id !== id);
          setSquads(updated);
          storageService.saveSquads(updated);
      }
  }

  // Common Input Class
  const inputClass = "w-full p-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 bg-white text-slate-900 placeholder-slate-400";
  const loginInputClass = "w-full p-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none bg-white text-slate-900 placeholder-slate-400";

  // --- Render ---

  if (isLoginView) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
        <div className="bg-white rounded-2xl p-8 max-w-md w-full shadow-2xl">
          <div className="flex justify-center mb-6">
             <img 
               src={CLUB_LOGO_URL} 
               alt={CLUB_NAME} 
               className="h-32 w-auto object-contain drop-shadow-md"
             />
          </div>
          <h1 className="text-xl font-bold text-center text-slate-800 mb-8">{CLUB_NAME}</h1>
          <form onSubmit={handleLogin} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Selecionar Utilizador</label>
              <select 
                className={loginInputClass}
                value={selectedLoginUserId}
                onChange={(e) => setSelectedLoginUserId(e.target.value)}
              >
                <option value="">Selecione...</option>
                {users.map(u => (
                    <option key={u.id} value={u.id}>{u.name} ({u.role})</option>
                ))}
              </select>
            </div>

            <button className="w-full py-3 bg-emerald-600 text-white font-bold rounded-lg hover:bg-emerald-700 transition shadow-lg mt-4">
              Entrar
            </button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <Layout user={currentUser!} currentView={currentView} onNavigate={setCurrentView} onLogout={handleLogout}>

      {/* DASHBOARD VIEW */}
      {currentView === 'DASHBOARD' && (
        <div className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
              <h3 className="text-slate-500 text-sm font-medium mb-1">Meus Atletas</h3>
              <p className="text-3xl font-bold text-slate-800">{visiblePlayers.length}</p>
            </div>
            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
              <h3 className="text-slate-500 text-sm font-medium mb-1">Escalões</h3>
              <p className="text-3xl font-bold text-emerald-600">{visibleSquads.length}</p>
            </div>
          </div>

          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
             <h3 className="text-lg font-bold text-slate-800 mb-4">Próximos Treinos</h3>
             {sessions.filter(s => visibleSquads.map(sq=>sq.id).includes(s.squadId)).length === 0 ? (
               <p className="text-slate-500 italic">Sem treinos agendados.</p>
             ) : (
               <div className="space-y-3">
                 {sessions
                   .filter(s => visibleSquads.map(sq=>sq.id).includes(s.squadId))
                   .sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime())
                   .slice(0, 5)
                   .map(s => (
                   <div key={s.id} className="flex flex-col sm:flex-row sm:items-center justify-between p-4 bg-slate-50 rounded-lg border border-slate-100">
                      <div className="mb-2 sm:mb-0">
                        <div className="font-semibold text-slate-800">{squads.find(sq => sq.id === s.squadId)?.name}</div>
                        <div className="text-sm text-slate-500">{s.date} às {s.time}</div>
                      </div>
                      <div className="text-sm px-3 py-1 bg-white rounded border border-slate-200 text-slate-600 self-start sm:self-center">
                        {s.description}
                      </div>
                   </div>
                 ))}
               </div>
             )}
          </div>
        </div>
      )}

      {/* PLAYERS VIEW */}
      {currentView === 'PLAYERS' && (
        <>
          {editingPlayer !== undefined ? (
            <PlayerForm 
              player={editingPlayer} 
              squads={visibleSquads} 
              onSave={savePlayer} 
              onCancel={() => setEditingPlayer(undefined)} 
            />
          ) : (
            <div className="space-y-6">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div className="relative w-full md:w-auto">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                  <input placeholder="Procurar atleta..." className={`pl-10 pr-4 ${inputClass} w-full md:w-64`} />
                </div>
                <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-2">
                  <select 
                    value={selectedSquadFilter}
