                                                    >
                                                        <span className={`w-6 h-6 flex items-center justify-center rounded-full text-xs font-bold mr-2 ${selectedTacticsPlayerId === p.id ? 'bg-white text-emerald-600' : 'bg-slate-400 text-slate-800'}`}>
                                                            {p.jerseyNumber}
