                                     <button onClick={() => setIsTacticsFullscreen(!isTacticsFullscreen)} className="p-2 rounded hover:bg-white/10">
                                         {isTacticsFullscreen ? <Minimize2 className="w-5 h-5" /> : <Maximize2 className="w-5 h-5" />}
                                     </button>
