                                          <span>Em Campo (Titulares)</span>
                                          <span>Minutos</span>
                                      </div>
                                      <div className="overflow-y-auto flex-1 p-2 space-y-2">
                                         {players
                                            .filter(p => matches.find(m => m.id === selectedMatchId)?.gameData?.starters.includes(p.id))
