                        ? 'bg-emerald-600 text-white border-emerald-600 shadow-md' 
                        : 'bg-white hover:bg-slate-50 border-slate-200 text-slate-700'
                    }`}
                  >
                     <button 
                        onClick={(e) => { e.stopPropagation(); openSessionModal(session); }}
