                      </div>

                      {/* Content Area */}
                      <div className="flex-1 overflow-y-auto p-4 bg-slate-50/50">

                          {/* CONVOCATORIA TAB */}
                          {activeGameTab === 'LINEUP' && (
                              <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
