                                </button>
                            )}
                        </div>
                      </div>
                   </div>
                 ))}
              </div>
           </div>
        </div>
      )}

    </Layout>
  );
};

export default App;

export enum UserRole {
  ADMIN = 'Administrador',
  COACH = 'Treinador',
  STAFF = 'Staff'
}

export enum AttendanceStatus {
  PRESENT = 'Presente',
  ABSENT = 'Ausente',
  LATE = 'Atrasado',
  INJURED = 'Lesionado'
}

export interface User {
  id: string;
  name: string;
  username: string;
  role: UserRole;
  password?: string;
  allowedSquads?: string[];
}

export interface Squad {
  id: string;
  name: string;
}

// New Interface for detailed player stats
export interface PlayerStats {
  technique: number; // 0-100
  speed: number;
  tactical: number;
  physical: number;
  behavior: string;
  strongFoot: 'Direito' | 'Esquerdo' | 'Ambos';
  positions: string;
}

export interface Player {
  id: string;
  squadId: string;
  name: string;
  address: string;
  birthDate: string;
  jerseyNumber: number | string;
  jerseyName: string;
  kitSize: string;
  tracksuitSize: string;
  notes: string;
  photoUrl?: string;
  emergencyName?: string;
  emergencyContact?: string;
  // New: Sports Sheet
  sportsDetails?: PlayerStats;
}

export interface TrainingSession {
  id: string;
  squadId: string;
  date: string;
  time: string;
  description: string;
  notes?: string; // Added notes field
}

export interface AttendanceRecord {
  id: string;
  sessionId: string;
  playerId: string;
  status: AttendanceStatus;
}

// Game Management Types
export interface MatchEvent {
  type: 'GOAL' | 'SUBSTITUTION' | 'CARD_YELLOW' | 'CARD_RED';
  minute: number;
  playerId: string;
  playerOutId?: string; // For substitutions
  note?: string;
}

export interface MatchData {
  starters: string[]; // IDs of players CURRENTLY on the field
  startingXI: string[]; // IDs of players who STARTED the game (Historical)
  substitutes: string[]; // IDs of players on bench
  formation: string; // e.g., "4-3-3", "4-4-2"
  events: MatchEvent[];
  playerMinutes: Record<string, number>; // Map playerId -> minutes played
  currentPeriod: 'PRE' | '1H' | 'HT' | '2H' | 'FT';
  timer: number; // Current second of the match
  isTimerRunning: boolean; // Controls if the timer is ticking
  // NEW: Coordinates for tactics board
  playerPositions: Record<string, {x: number, y: number}>; // x, y in percentages (0-100)
}

export interface Match {
  id: string;
  squadId: string;
  date: string;
  time: string;
  opponent: string;
  location: 'Casa' | 'Fora';
  venue?: string; // Specific field name (especially for Away games)
  convokedIds: string[];
  notes?: string;
  // New Fields
  playerKit?: string;
  goalkeeperKit?: string;
  gameData?: MatchData; // Stores the live game state
}

export type ViewState = 'DASHBOARD' | 'PLAYERS' | 'TRAINING' | 'MATCHES' | 'ADMIN';

import { User, Squad, Player, TrainingSession, AttendanceRecord, Match } from '../types';
import { supabase } from './supabaseClient';

// Helper to map DB result to types if necessary, though we used quoted columns in SQL to match keys.

export const storageService = {
  // --- USERS ---
  getUsers: async (): Promise<User[]> => {
    const { data, error } = await supabase.from('users').select('*');
    if (error) { console.error('Error fetching users:', error); return []; }
    return data || [];
  },

  saveUsers: async (users: User[]) => {
    // In a real scenario we would optimize this, but for sync compatibility we upsert
    // WARNING: This replaces local storage logic. In a real DB app, you usually insert/update single items.
    // To keep the app logic simple without rewriting the whole App.tsx state management:
    // We will loop and upsert. Ideally, App.tsx should call specific add/update functions.

    // For this migration, we assume the App.tsx sends the WHOLE array. 
    // We will iterate and upsert based on ID.
    for (const u of users) {
       const { error } = await supabase.from('users').upsert(u);
       if(error) console.error('Error saving user', u.name, error);
    }
  },

  deleteUser: async (id: string) => {
      await supabase.from('users').delete().eq('id', id);
  },

  // --- SQUADS ---
  getSquads: async (): Promise<Squad[]> => {
    const { data, error } = await supabase.from('squads').select('*');
    if (error) { console.error('Error fetching squads:', error); return []; }
    return data || [];
  },

  saveSquads: async (squads: Squad[]) => {
    for (const s of squads) {
        await supabase.from('squads').upsert(s);
    }
  },

  deleteSquad: async (id: string) => {
      await supabase.from('squads').delete().eq('id', id);
  },

  // --- PLAYERS ---
  getPlayers: async (): Promise<Player[]> => {
    const { data, error } = await supabase.from('players').select('*');
    if (error) { console.error('Error fetching players:', error); return []; }
    return data || [];
  },

  savePlayers: async (players: Player[]) => {
     for (const p of players) {
         await supabase.from('players').upsert(p);
     }
  },

  deletePlayer: async (id: string) => {
      await supabase.from('players').delete().eq('id', id);
  },

  // --- SESSIONS ---
  getSessions: async (): Promise<TrainingSession[]> => {
    const { data, error } = await supabase.from('sessions').select('*');
    if (error) { console.error('Error fetching sessions:', error); return []; }
    return data || [];
  },

  saveSessions: async (sessions: TrainingSession[]) => {
     for(const s of sessions) {
         await supabase.from('sessions').upsert(s);
     }
  },

  deleteSession: async (id: string) => {
      await supabase.from('sessions').delete().eq('id', id);
  },

  // --- ATTENDANCE ---
  getAttendance: async (): Promise<AttendanceRecord[]> => {
    const { data, error } = await supabase.from('attendance').select('*');
    if (error) { console.error('Error fetching attendance:', error); return []; }
    return data || [];
  },

  saveAttendance: async (records: AttendanceRecord[]) => {
     // This list can be huge. In a real app, optimize. 
     // We will upsert in batches or just the changed ones if refactored.
     // For now, adhering to the "save list" pattern:
     if(records.length > 0) {
        const { error } = await supabase.from('attendance').upsert(records);
        if (error) console.error('Error saving attendance', error);
     }
  },

  deleteAttendance: async (playerId: string, sessionId: string) => {
      await supabase.from('attendance').delete().match({ playerId, sessionId });
  },

  // --- MATCHES ---
  getMatches: async (): Promise<Match[]> => {
    const { data, error } = await supabase.from('matches').select('*');
    if (error) { console.error('Error fetching matches:', error); return []; }
    return data || [];
  },

  saveMatches: async (matches: Match[]) => {
      for(const m of matches) {
          await supabase.from('matches').upsert(m);
      }
  },

  deleteMatch: async (id: string) => {
      await supabase.from('matches').delete().eq('id', id);
  },

  // --- AUTH (Simplified for this app structure) ---
  // Note: Standard Supabase Auth uses email/password. 
  // Since this app uses a custom "User Table" approach, we keep fetching from table.

  logout: () => {
    localStorage.removeItem('coachpro_current_user');
  },

  getCurrentUser: (): User | null => {
      const stored = localStorage.getItem('coachpro_current_user');
      return stored ? JSON.parse(stored) : null;
  },

  persistLogin: (user: User) => {
      localStorage.setItem('coachpro_current_user', JSON.stringify(user));
  }
};

import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { Match, Squad, Player, TrainingSession, AttendanceRecord, AttendanceStatus } from '../types';
import { CLUB_NAME } from '../constants';

// Removed getDataUrl function as logo is no longer needed

const addHeader = async (doc: jsPDF, title: string, subtitle: string) => {
    const primaryColor = [16, 185, 129]; // Emerald 500
    const darkColor = [30, 41, 59]; // Slate 800

    // No Logo logic here anymore as requested

    // -- Header --
    doc.setFontSize(22);
    doc.setTextColor(primaryColor[0], primaryColor[1], primaryColor[2]);
    doc.text(CLUB_NAME, 14, 22);

    doc.setFontSize(12);
    doc.setTextColor(100, 100, 100);
    doc.text(subtitle, 14, 28);

    // -- Title --
    doc.setFontSize(18);
    doc.setTextColor(darkColor[0], darkColor[1], darkColor[2]);
    doc.text(title.toUpperCase(), 14, 45);

    return 55; // Return Y position for next element
}

const addFooter = (doc: jsPDF) => {
    const pageHeight = doc.internal.pageSize.height;
    doc.setFontSize(8);
    doc.setTextColor(150, 150, 150);
    doc.text(`Documento gerado automaticamente por ${CLUB_NAME} Manager`, 14, pageHeight - 10);
}

// 1. CONVOCATORIA PDF
export const generateConvocationPDF = async (
  match: Match, 
  squad: Squad, 
  players: Player[]
) => {
  const doc = new jsPDF();
  const startY = await addHeader(doc, `CONVOCATÓRIA - ${squad.name}`, "Gestão de Equipas");

  // -- Match Details --
  doc.setFontSize(11);
  doc.setTextColor(0, 0, 0);

  let detailsY = startY;
  doc.setFont("helvetica", "bold");
  doc.text("Adversário:", 14, detailsY);
  doc.setFont("helvetica", "normal");
  doc.text(match.opponent, 40, detailsY);

  doc.setFont("helvetica", "bold");
  doc.text("Data/Hora:", 14, detailsY + 6);
  doc.setFont("helvetica", "normal");
  doc.text(`${match.date} às ${match.time}`, 40, detailsY + 6);

  doc.setFont("helvetica", "bold");
  doc.text("Local:", 14, detailsY + 12);
  doc.setFont("helvetica", "normal");
  const venueText = match.venue ? `${match.location} (${match.venue})` : match.location;
  doc.text(venueText, 40, detailsY + 12);

  if (match.playerKit || match.goalkeeperKit) {
     detailsY += 6;
     doc.setFont("helvetica", "bold");
     doc.text("Equipamentos:", 14, detailsY + 12);
     doc.setFont("helvetica", "normal");
     let kitText = "";
     if(match.playerKit) kitText += `Jogadores: ${match.playerKit} `;
     if(match.goalkeeperKit) kitText += `| GR: ${match.goalkeeperKit}`;
     doc.text(kitText, 45, detailsY + 12);
     detailsY += 6;
  }

  // -- Players Table --
  const sortedPlayers = [...players].sort((a, b) => Number(a.jerseyNumber) - Number(b.jerseyNumber));
  const tableData = sortedPlayers.map(p => [p.jerseyNumber, p.name, p.jerseyName || '-']);

  autoTable(doc, {
    startY: detailsY + 20,
    head: [['#', 'Nome Completo', 'Nome Camisola']],
    body: tableData,
    theme: 'grid',
    headStyles: { fillColor: [16, 185, 129], textColor: 255, fontStyle: 'bold' },
    styles: { fontSize: 10, cellPadding: 3 },
    alternateRowStyles: { fillColor: [240, 253, 244] }
  });

  // -- Notes --
  if (match.notes) {
    const finalY = (doc as any).lastAutoTable.finalY + 10;
    doc.setFontSize(10);
    doc.setTextColor(16, 185, 129);
    doc.setFont("helvetica", "bold");
    doc.text("OBSERVAÇÕES:", 14, finalY);

    doc.setFontSize(10);
    doc.setTextColor(0, 0, 0);
    doc.setFont("helvetica", "normal");
    const splitNotes = doc.splitTextToSize(match.notes, 180);
    doc.text(splitNotes, 14, finalY + 5);
  }

  addFooter(doc);
  doc.save(`Convocatoria_${squad.name}_vs_${match.opponent.replace(/\s+/g, '_')}.pdf`);
};

// 2. FICHA DE JOGO PDF (MATCH SHEET - Minutes & Obs)
export const generateMatchSheetPDF = async (
    match: Match,
    squad: Squad,
    players: Player[]
) => {
    const doc = new jsPDF();
    const startY = await addHeader(doc, `FICHA DE JOGO - ${squad.name}`, "Relatório de Jogo");

    // -- Calculate Result --
    const goalsUs = match.gameData?.events?.filter(e => e.type === 'GOAL' && e.playerId !== 'opponent').length || 0;
    const goalsThem = match.gameData?.events?.filter(e => e.type === 'GOAL' && e.playerId === 'opponent').length || 0;

    // -- Match Details --
    doc.setFontSize(11);
    doc.setTextColor(0, 0, 0);
    let detailsY = startY;

    // Line 1: Opponent
    doc.setFont("helvetica", "bold"); doc.text("Adversário:", 14, detailsY);
    doc.setFont("helvetica", "normal"); doc.text(match.opponent, 40, detailsY);

    // Result Display (Prominent)
    doc.setFontSize(16);
    doc.setFont("helvetica", "bold");
    doc.setTextColor(30, 41, 59); // Slate 800
    doc.text(`${goalsUs} - ${goalsThem}`, 150, detailsY);
    doc.setFontSize(11);
    doc.setTextColor(0, 0, 0);

    // Line 2: Date
    doc.setFont("helvetica", "bold"); doc.text("Data:", 14, detailsY + 6);
    doc.setFont("helvetica", "normal"); doc.text(`${match.date} ${match.time}`, 40, detailsY + 6);

    // Line 3: Location
    doc.setFont("helvetica", "bold"); doc.text("Local:", 14, detailsY + 12);
    doc.setFont("helvetica", "normal");
    const venueText = match.venue ? `${match.location} (${match.venue})` : match.location;
    doc.text(venueText, 40, detailsY + 12);

    // -- Stats Table --
    // Filter only players that were convoked
    const matchPlayers = players.filter(p => match.convokedIds.includes(p.id))
        .sort((a,b) => Number(a.jerseyNumber) - Number(b.jerseyNumber));

    const tableData = matchPlayers.map(p => {
        const minutes = match.gameData?.playerMinutes?.[p.id] || 0;
        const isStarter = match.gameData?.startingXI?.includes(p.id) || match.gameData?.starters?.includes(p.id) || false;

        // Count goals from events
        const goals = match.gameData?.events?.filter(e => e.type === 'GOAL' && e.playerId === p.id).length || 0;
        const cards = match.gameData?.events?.filter(e => (e.type === 'CARD_YELLOW' || e.type === 'CARD_RED') && e.playerId === p.id).length || 0;

        return [
            p.jerseyNumber,
            p.name,
            isStarter ? 'Titular' : 'Sup',
            minutes + "'",
            goals > 0 ? goals.toString() : '-',
            cards > 0 ? cards.toString() : '-'
        ];
    });

    autoTable(doc, {
        startY: detailsY + 20,
        head: [['#', 'Nome', 'Início', 'Minutos', 'Golos', 'Cartões']],
        body: tableData,
        theme: 'grid',
        headStyles: { fillColor: [30, 41, 59], textColor: 255, fontStyle: 'bold' }, // Darker header for report
        styles: { fontSize: 10, cellPadding: 3 },
        alternateRowStyles: { fillColor: [241, 245, 249] } // Slate 50
    });

    // -- Observations Field (Large Box) --
    let finalY = (doc as any).lastAutoTable.finalY + 15;

    // Check if we need a new page
    if (finalY > 250) {
        doc.addPage();
        finalY = 20;
    }

    doc.setFontSize(12);
    doc.setTextColor(0,0,0);
    doc.setFont("helvetica", "bold");
    doc.text("COMENTÁRIOS / CRÓNICA DE JOGO:", 14, finalY);

    // Pre-filled notes if existing
    if (match.notes) {
        doc.setFont("helvetica", "normal");
        doc.setFontSize(10);
        const splitNotes = doc.splitTextToSize(match.notes, 180);
        doc.text(splitNotes, 14, finalY + 7);
        finalY += (splitNotes.length * 5) + 5;
    } else {
        // Draw a box for manual writing if printed
        doc.setDrawColor(200, 200, 200);
        doc.rect(14, finalY + 2, 182, 40); // x, y, w, h
    }

    addFooter(doc);
    doc.save(`FichaJogo_${match.date}_${match.opponent}.pdf`);
}

// 3. RELATÓRIO DE TREINO (TRAINING SHEET - Attendance & Obs)
export const generateTrainingSessionPDF = async (
    session: TrainingSession,
    squad: Squad,
    players: Player[],
    attendance: AttendanceRecord[]
) => {
    const doc = new jsPDF();
    const startY = await addHeader(doc, `TREINO - ${squad.name}`, "Relatório de Treino");

    // -- Session Details --
    doc.setFontSize(11);
    doc.setTextColor(0, 0, 0);
    let detailsY = startY;

    doc.setFont("helvetica", "bold"); doc.text("Data:", 14, detailsY);
    doc.setFont("helvetica", "normal"); doc.text(`${session.date} às ${session.time}`, 30, detailsY);

    doc.setFont("helvetica", "bold"); doc.text("Descrição:", 14, detailsY + 6);
    doc.setFont("helvetica", "normal"); doc.text(session.description, 35, detailsY + 6);

    // -- Attendance Table --
    const squadPlayers = players.filter(p => p.squadId === session.squadId)
        .sort((a,b) => Number(a.jerseyNumber) - Number(b.jerseyNumber));

    const tableData = squadPlayers.map(p => {
        const record = attendance.find(a => a.sessionId === session.id && a.playerId === p.id);
        const status = record?.status || "N/A";
        return [p.jerseyNumber, p.name, status];
    });

    // Calculate Summary
    const presentCount = attendance.filter(a => a.sessionId === session.id && a.status === AttendanceStatus.PRESENT).length;
    const absentCount = attendance.filter(a => a.sessionId === session.id && a.status === AttendanceStatus.ABSENT).length;
    const injuredCount = attendance.filter(a => a.sessionId === session.id && a.status === AttendanceStatus.INJURED).length;

    doc.setFontSize(10);
    doc.text(`Presentes: ${presentCount} | Ausentes: ${absentCount} | Lesionados: ${injuredCount}`, 14, detailsY + 15);

    autoTable(doc, {
        startY: detailsY + 20,
        head: [['#', 'Nome', 'Presença']],
        body: tableData,
        theme: 'grid',
        headStyles: { fillColor: [16, 185, 129], textColor: 255, fontStyle: 'bold' },
        styles: { fontSize: 10, cellPadding: 3 },
        alternateRowStyles: { fillColor: [240, 253, 244] },
        didParseCell: function(data) {
            if (data.section === 'body' && data.column.index === 2) {
                const text = data.cell.raw as string;
                if (text === AttendanceStatus.PRESENT) data.cell.styles.textColor = [21, 128, 61]; // Green
                else if (text === AttendanceStatus.ABSENT) data.cell.styles.textColor = [185, 28, 28]; // Red
                else if (text === AttendanceStatus.INJURED) data.cell.styles.textColor = [194, 65, 12]; // Orange
            }
        }
    });

    // -- Observations Field --
    let finalY = (doc as any).lastAutoTable.finalY + 15;
    if (finalY > 250) { doc.addPage(); finalY = 20; }

    doc.setFontSize(12);
    doc.setTextColor(0,0,0);
    doc.setFont("helvetica", "bold");
    doc.text("OBSERVAÇÕES DO TREINO:", 14, finalY);

    if (session.notes) {
        doc.setFont("helvetica", "normal");
        doc.setFontSize(10);
        const splitNotes = doc.splitTextToSize(session.notes, 180);
        doc.text(splitNotes, 14, finalY + 7);
    } else {
        // Box for manual writing
        doc.setDrawColor(200, 200, 200);
        doc.rect(14, finalY + 2, 182, 50);
    }

    addFooter(doc);
    doc.save(`Treino_${squad.name}_${session.date}.pdf`);
}

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  User, Squad, Player, TrainingSession, AttendanceRecord, ViewState, UserRole, AttendanceStatus, Match, MatchData, MatchEvent 
} from './types';
import { storageService } from './services/storageService';
import { generateConvocationPDF, generateMatchSheetPDF, generateTrainingSessionPDF } from './services/pdfService';
import { CLUB_NAME, CLUB_LOGO_URL } from './constants';
import Layout from './components/Layout';
import PlayerForm from './components/PlayerForm';
import { 
  Plus, Search, Filter, Trash2, Edit2, Check, X as XIcon, AlertCircle, Clock, Save, UserPlus, Users, UserCircle, CalendarDays, KeyRound, Flag, Copy, FileDown, Loader2, Play, Pause, Square, Shirt, Shield, ArrowRightLeft, FileText, Move, Maximize2, Minimize2, UserMinus, UserCheck, Printer, RefreshCcw, Trophy, Minus, PlusCircle, RotateCcw
} from 'lucide-react';

const App: React.FC = () => {
  // Global State
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<ViewState>('DASHBOARD');
  const [isLoading, setIsLoading] = useState(false);

  // Data State
  const [users, setUsers] = useState<User[]>([]);
  const [squads, setSquads] = useState<Squad[]>([]);
  const [players, setPlayers] = useState<Player[]>([]);
  const [sessions, setSessions] = useState<TrainingSession[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [matches, setMatches] = useState<Match[]>([]);

  // UI State
  const [isLoginView, setIsLoginView] = useState(true);
  const [selectedLoginUserId, setSelectedLoginUserId] = useState('');
  const [loginPassword, setLoginPassword] = useState(''); 
  const [loginError, setLoginError] = useState('');

  const [editingPlayer, setEditingPlayer] = useState<Player | null | undefined>(undefined); 
  const [selectedSquadFilter, setSelectedSquadFilter] = useState<string>('all');

  // Training/Attendance UI State
  const [isSessionModalOpen, setIsSessionModalOpen] = useState(false);
  const [editingSession, setEditingSession] = useState<Partial<TrainingSession>>({});
  const [selectedSessionId, setSelectedSessionId] = useState<string | null>(null);

  // Matches UI State
  const [isMatchModalOpen, setIsMatchModalOpen] = useState(false);
  const [editingMatch, setEditingMatch] = useState<Partial<Match>>({});
  const [selectedMatchId, setSelectedMatchId] = useState<string | null>(null);
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);

  // Game Day UI State
  const [activeGameTab, setActiveGameTab] = useState<'LINEUP' | 'TACTICS' | 'LIVE'>('LINEUP');

  // Tactics Selection State
  const [selectedTacticsPlayerId, setSelectedTacticsPlayerId] = useState<string | null>(null);
  const [isTacticsFullscreen, setIsTacticsFullscreen] = useState(false);
  const [isLiveGameFullscreen, setIsLiveGameFullscreen] = useState(false);
  const [draggingPlayerId, setDraggingPlayerId] = useState<string | null>(null);
  const fieldRef = useRef<HTMLDivElement>(null);

  // --- TIMER LOGIC ---
  const timerRef = useRef<any>(null);

  useEffect(() => {
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, []);

  // Timer Tick
  useEffect(() => {
    if (selectedMatchId && matches.length > 0) {
      const match = matches.find(m => m.id === selectedMatchId);

      // Only tick if period is active AND timer is running
      if (match?.gameData?.isTimerRunning && (match.gameData.currentPeriod === '1H' || match.gameData.currentPeriod === '2H')) {
          if (!timerRef.current) {
            timerRef.current = setInterval(() => {
                setMatches(prevMatches => {
                    return prevMatches.map(m => {
                        if (m.id === selectedMatchId && m.gameData?.isTimerRunning) {
                             const newTimer = m.gameData.timer + 1;

                             // Update Minutes Played every 60s
                             const newPlayerMinutes = { ...m.gameData.playerMinutes };

                             // We update minute count every 60 seconds of game time
                             if (newTimer > 0 && newTimer % 60 === 0) {
                                 m.gameData.starters.forEach(pid => {
                                     newPlayerMinutes[pid] = (newPlayerMinutes[pid] || 0) + 1;
                                 });
                             }

                             return {
                                 ...m,
                                 gameData: {
                                     ...m.gameData,
                                     timer: newTimer,
                                     playerMinutes: newPlayerMinutes
                                 }
                             };
                        }
                        return m;
                    });
                });
            }, 1000); 
          }
      } else {
          if (timerRef.current) {
              clearInterval(timerRef.current);
              timerRef.current = null;
          }
      }
    }
  }, [selectedMatchId, matches]);

  // Initial Load & Admin Check
  useEffect(() => {
    const init = async () => {
        setIsLoading(true);
        // We need to fetch users to display the login dropdown
        let loadedUsers = await storageService.getUsers();

        // --- SEED DEFAULT ADMIN IF NO USERS EXIST ---
        if (loadedUsers.length === 0) {
            const defaultAdmin: User = {
                id: crypto.randomUUID(),
                name: 'Administrador',
                username: 'admin',
                role: UserRole.ADMIN,
                password: '123',
                allowedSquads: []
            };
            await storageService.saveUsers([defaultAdmin]);
            loadedUsers = [defaultAdmin];
        }

        setUsers(loadedUsers);

        const user = storageService.getCurrentUser();
        if (user) {
          // Verify if user still exists in DB (security check)
          const validUser = loadedUsers.find(u => u.id === user.id);
          if (validUser) {
              setCurrentUser(validUser); // Update with fresh data (e.g. if role changed)
              setIsLoginView(false);
              await loadData();
          } else {
              storageService.logout();
              setIsLoginView(true);
          }
        }
        setIsLoading(false);
    };
    init();
  }, []);

  const loadData = async () => {
    // Parallel fetching for performance
    const [u, s, p, sess, att, m] = await Promise.all([
        storageService.getUsers(),
        storageService.getSquads(),
        storageService.getPlayers(),
        storageService.getSessions(),
        storageService.getAttendance(),
        storageService.getMatches()
    ]);

    setUsers(u);
    setSquads(s);
    setPlayers(p);
    setSessions(sess);
    setAttendance(att);
    setMatches(m);
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoginError('');
    if(!selectedLoginUserId) return;

    // Always re-fetch users on login attempt to ensure we have latest passwords
    const latestUsers = await storageService.getUsers();
    setUsers(latestUsers);

    const user = latestUsers.find(u => u.id === selectedLoginUserId);
    if (user) {
        // Strict Password Check
        if (user.password !== loginPassword) {
            setLoginError('Password incorreta.');
            return;
        }

        storageService.persistLogin(user);
        setCurrentUser(user);
        setIsLoading(true);
        await loadData();
        setIsLoading(false);
        setIsLoginView(false);
    }
  };

  const handleLogout = () => {
    storageService.logout();
    setCurrentUser(null);
    setIsLoginView(true);
    setSelectedLoginUserId('');
    setLoginPassword('');
    setLoginError('');
  };

  // --- Helper: Visible Squads for Current User ---
  const visibleSquads = useMemo(() => {
    if (!currentUser) return [];
    if (currentUser.role === UserRole.ADMIN) return squads;
    if (!currentUser.allowedSquads || currentUser.allowedSquads.length === 0) return [];
    return squads.filter(s => currentUser.allowedSquads?.includes(s.id));
  }, [squads, currentUser]);

  const visiblePlayers = useMemo(() => {
    const squadIds = visibleSquads.map(s => s.id);
    return players.filter(p => squadIds.includes(p.squadId));
  }, [players, visibleSquads]);

  // --- Logic for Players ---
  const savePlayer = async (player: Player) => {
    let updatedPlayers;
    if (players.find(p => p.id === player.id)) {
      updatedPlayers = players.map(p => p.id === player.id ? player : p);
    } else {
      updatedPlayers = [...players, player];
    }
    setPlayers(updatedPlayers); // Optimistic Update
    setEditingPlayer(undefined);
    await storageService.savePlayers([player]); // Save to DB
  };

  const deletePlayer = async (id: string) => {
    if (confirm("Tem a certeza que deseja eliminar este atleta?")) {
      const updated = players.filter(p => p.id !== id);
      setPlayers(updated); // Optimistic
      await storageService.deletePlayer(id); // DB
    }
  };

  const filteredPlayers = useMemo(() => {
    let filtered = visiblePlayers;
    if (selectedSquadFilter !== 'all') {
      filtered = filtered.filter(p => p.squadId === selectedSquadFilter);
    }
    return filtered.sort((a,b) => (a.jerseyNumber as number) - (b.jerseyNumber as number));
  }, [visiblePlayers, selectedSquadFilter]);

  const calculateAge = (birthDateStr: string) => {
    if (!birthDateStr) return '-';
    const birth = new Date(birthDateStr);
    const now = new Date();
    let age = now.getFullYear() - birth.getFullYear();
    const m = now.getMonth() - birth.getMonth();
    if (m < 0 || (m === 0 && now.getDate() < birth.getDate())) {
      age--;
    }
    return age;
  };

  const copySquadList = () => {
    if (selectedSquadFilter === 'all') {
        alert("Por favor selecione um escalão específico para exportar a listagem.");
        return;
    }
    const squad = squads.find(s => s.id === selectedSquadFilter);
    let text = `LISTAGEM - ${squad?.name.toUpperCase()}\n\n`;
    filteredPlayers.forEach(p => {
        text += `${p.jerseyNumber}. ${p.name} (${calculateAge(p.birthDate)} anos)\n`;
    });

    navigator.clipboard.writeText(text);
    alert("Listagem copiada para a área de transferência!");
  };

  // --- Logic for Training ---
  const openSessionModal = (session?: TrainingSession) => {
      setEditingSession(session || { date: new Date().toISOString().split('T')[0], time: '19:00', squadId: visibleSquads[0]?.id });
      setIsSessionModalOpen(true);
  }

  const saveSession = async () => {
    if (!editingSession.date || !editingSession.squadId) return;

    let sessionToSave: TrainingSession;
    let updatedSessions = [...sessions];

    if (editingSession.id) {
        // Edit
        sessionToSave = { ...editingSession } as TrainingSession;
        updatedSessions = updatedSessions.map(s => s.id === editingSession.id ? sessionToSave : s);
    } else {
        // Create
        sessionToSave = {
            id: crypto.randomUUID(),
            date: editingSession.date!,
            squadId: editingSession.squadId!,
            time: editingSession.time || '19:00',
            description: editingSession.description || 'Treino',
            notes: editingSession.notes || ''
        };
        updatedSessions.push(sessionToSave);
    }

    setSessions(updatedSessions); // Optimistic
    setIsSessionModalOpen(false);
    setEditingSession({});
    await storageService.saveSessions([sessionToSave]); // DB
  };

  const deleteSession = async (id: string) => {
      if(confirm('Eliminar esta sessão de treino? Os registos de presença serão perdidos.')) {
          const updated = sessions.filter(s => s.id !== id);
          setSessions(updated);
          if (selectedSessionId === id) setSelectedSessionId(null);
          await storageService.deleteSession(id);
      }
  };

  const toggleAttendance = async (playerId: string, sessionId: string, status: AttendanceStatus) => {
    const existingIndex = attendance.findIndex(a => a.playerId === playerId && a.sessionId === sessionId);
    let newAttendance = [...attendance];
    let recordToSave: AttendanceRecord;

    if (existingIndex >= 0) {
      if (newAttendance[existingIndex].status === status) {
        // Toggle OFF - Remove
        await storageService.deleteAttendance(playerId, sessionId);
        newAttendance.splice(existingIndex, 1);
        setAttendance(newAttendance);
        return;
      } else {
        newAttendance[existingIndex].status = status;
        recordToSave = newAttendance[existingIndex];
      }
    } else {
      recordToSave = { id: crypto.randomUUID(), playerId, sessionId, status };
      newAttendance.push(recordToSave);
    }
    setAttendance(newAttendance);
    await storageService.saveAttendance([recordToSave]);
  };

  const getAttendanceStatus = (playerId: string, sessionId: string | null) => {
    if (!sessionId) return undefined;
    const record = attendance.find(a => a.playerId === playerId && a.sessionId === sessionId);
    return record?.status;
  };

  const downloadTrainingPDF = async (sessionId: string) => {
    const session = sessions.find(s => s.id === sessionId);
    if(!session) return;
    const squad = squads.find(s => s.id === session.squadId);
    if(!squad) return;

    try {
        await generateTrainingSessionPDF(session, squad, players, attendance);
    } catch(e) {
        console.error(e);
        alert("Erro ao gerar PDF.");
    }
  }

  // --- Logic for Matches (Convocatórias & Game Day) ---
  const openMatchModal = (match?: Match) => {
      setEditingMatch(match || { 
          date: new Date().toISOString().split('T')[0], 
          time: '15:00', 
          squadId: visibleSquads[0]?.id,
          location: 'Casa',
          venue: ''
      });
      setIsMatchModalOpen(true);
  }

  const saveMatch = async () => {
    if (!editingMatch.date || !editingMatch.squadId || !editingMatch.opponent) return;

    let matchToSave: Match;
    let updatedMatches = [...matches];

    if (editingMatch.id) {
        matchToSave = { ...editingMatch } as Match;
        updatedMatches = updatedMatches.map(m => m.id === editingMatch.id ? matchToSave : m);
    } else {
        matchToSave = {
            id: crypto.randomUUID(),
            squadId: editingMatch.squadId!,
            date: editingMatch.date!,
            time: editingMatch.time || '15:00',
            opponent: editingMatch.opponent!,
            location: editingMatch.location as 'Casa' | 'Fora' || 'Casa',
            venue: editingMatch.venue,
            convokedIds: [],
            notes: editingMatch.notes || '',
            playerKit: editingMatch.playerKit,
            goalkeeperKit: editingMatch.goalkeeperKit
        };
        updatedMatches.push(matchToSave);
    }
    setMatches(updatedMatches);
    setIsMatchModalOpen(false);
    setEditingMatch({});
    await storageService.saveMatches([matchToSave]);
  };

  const deleteMatch = async (id: string) => {
      if(confirm('Eliminar este jogo? Todos os dados (golos, estatísticas) serão perdidos e removidos do histórico dos atletas.')) {
          const updated = matches.filter(m => m.id !== id);
          setMatches(updated);
          if (selectedMatchId === id) setSelectedMatchId(null);
          await storageService.deleteMatch(id);
      }
  };

  const updateMatchGameData = async (matchId: string, data: Partial<MatchData>) => {
      let matchToUpdate: Match | undefined;
      const updatedMatches = matches.map(m => {
          if (m.id === matchId) {
              const prevData = m.gameData || {
                  starters: [],
                  startingXI: [],
                  substitutes: [],
                  formation: '4-3-3',
                  events: [],
                  playerMinutes: {},
                  playerPositions: {},
                  currentPeriod: 'PRE',
                  timer: 0,
                  isTimerRunning: false
              };
              matchToUpdate = { ...m, gameData: { ...prevData, ...data } };
              return matchToUpdate;
          }
          return m;
      });
      setMatches(updatedMatches);
      if(matchToUpdate) await storageService.saveMatches([matchToUpdate]);
  };

  const toggleConvocation = async (matchId: string, playerId: string) => {
    const match = matches.find(m => m.id === matchId);
    if (!match) return;

    let newConvoked = [...match.convokedIds];
    let updatedGameData = match.gameData;

    if (newConvoked.includes(playerId)) {
      // Remove
      newConvoked = newConvoked.filter(id => id !== playerId);
      if (match.gameData) {
          updatedGameData = {
              ...match.gameData,
              starters: match.gameData.starters.filter(id => id !== playerId),
              startingXI: (match.gameData.startingXI || []).filter(id => id !== playerId),
              substitutes: match.gameData.substitutes.filter(id => id !== playerId)
          };
      }
    } else {
      // Add
      newConvoked.push(playerId);
    }

    const updatedMatch = { ...match, convokedIds: newConvoked, gameData: updatedGameData };
    const updatedMatches = matches.map(m => m.id === matchId ? updatedMatch : m);

    setMatches(updatedMatches);
    await storageService.saveMatches([updatedMatch]);
  };

  // Helper to toggle starter status directly from list
  const toggleStarterStatus = (matchId: string, playerId: string, e: React.MouseEvent) => {
      e.stopPropagation();
      const match = matches.find(m => m.id === matchId);
      if(!match) return;

      const currentStarters = match.gameData?.starters || [];
      const currentStartingXI = match.gameData?.startingXI || [];

      let newStarters = [...currentStarters];
      let newStartingXI = [...currentStartingXI];

      if (newStarters.includes(playerId)) {
          // Move to Bench
          newStarters = newStarters.filter(id => id !== playerId);
          // Also remove from historical starting XI if we are still in setup phase (not live)
          // For simplicity, we always sync them in this view
          newStartingXI = newStartingXI.filter(id => id !== playerId);
      } else {
          // Move to Starters
          newStarters.push(playerId);
          if (!newStartingXI.includes(playerId)) newStartingXI.push(playerId);
      }

      updateMatchGameData(matchId, { starters: newStarters, startingXI: newStartingXI });
  };

  // --- TACTICS BOARD LOGIC (DRAG & DROP) ---
  const handlePointerDown = (e: React.PointerEvent, playerId: string) => {
      e.stopPropagation();
      e.currentTarget.setPointerCapture(e.pointerId);
      setDraggingPlayerId(playerId);
      // Ensure player is in starters if not already
      const match = matches.find(m => m.id === selectedMatchId);
      if (match && !match.gameData?.starters.includes(playerId)) {
          const newStarters = [...(match.gameData?.starters || []), playerId];
          const newStartingXI = [...(match.gameData?.startingXI || []), playerId];
          updateMatchGameData(match.id, {
              starters: newStarters,
              startingXI: newStartingXI
          });
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
      if (!draggingPlayerId || !fieldRef.current || !selectedMatchId) return;

      const rect = fieldRef.current.getBoundingClientRect();
      const x = Math.max(0, Math.min(100, ((e.clientX - rect.left) / rect.width) * 100));
      const y = Math.max(0, Math.min(100, ((e.clientY - rect.top) / rect.height) * 100));

      const match = matches.find(m => m.id === selectedMatchId);
      if (match) {
           const currentPositions = match.gameData?.playerPositions || {};
           updateMatchGameData(selectedMatchId, {
               playerPositions: { ...currentPositions, [draggingPlayerId]: { x, y } }
           });
      }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
      setDraggingPlayerId(null);
      e.currentTarget.releasePointerCapture(e.pointerId);
  };

  // Also support click-to-place for non-drag interaction
  const handleFieldClick = (e: React.MouseEvent) => {
      if (!selectedTacticsPlayerId || !selectedMatchId || !fieldRef.current) return;

      const rect = fieldRef.current.getBoundingClientRect();
      const x = ((e.clientX - rect.left) / rect.width) * 100;
      const y = ((e.clientY - rect.top) / rect.height) * 100;

      const match = matches.find(m => m.id === selectedMatchId);
      if(match) {
          const currentStarters = match.gameData?.starters || [];
          let newStarters = [...currentStarters];
          if(!newStarters.includes(selectedTacticsPlayerId)) newStarters.push(selectedTacticsPlayerId);

          // Sync Starting XI
          const currentStartingXI = match.gameData?.startingXI || [];
          let newStartingXI = [...currentStartingXI];
          if(!newStartingXI.includes(selectedTacticsPlayerId)) newStartingXI.push(selectedTacticsPlayerId);

          updateMatchGameData(selectedMatchId, {
              starters: newStarters,
              startingXI: newStartingXI,
              playerPositions: { ...(match.gameData?.playerPositions || {}), [selectedTacticsPlayerId]: { x, y } }
          });
          setSelectedTacticsPlayerId(null);
      }
  };

  const removeStarter = (playerId: string) => {
      if (!selectedMatchId) return;
      const match = matches.find(m => m.id === selectedMatchId);
      if(!match) return;

      const newStarters = (match.gameData?.starters || []).filter(id => id !== playerId);
      const newStartingXI = (match.gameData?.startingXI || []).filter(id => id !== playerId);

      updateMatchGameData(selectedMatchId, { starters: newStarters, startingXI: newStartingXI });
  };

  // --- LIVE GAME LOGIC ---
  const handleSubstitution = (matchId: string, playerOutId: string, playerInId: string) => {
      const match = matches.find(m => m.id === matchId);
      if(!match) return;

      const newStarters = (match.gameData?.starters || []).filter(id => id !== playerOutId);
      newStarters.push(playerInId);

      // We could also record an event here
      const minute = Math.ceil((match.gameData?.timer || 0) / 60);
      const subEvent: MatchEvent = {
          type: 'SUBSTITUTION',
          minute,
          playerId: playerInId,
          playerOutId: playerOutId
      };
      const newEvents = [...(match.gameData?.events || []), subEvent];

      updateMatchGameData(matchId, { starters: newStarters, events: newEvents });
  };

  const toggleTimer = (matchId: string) => {
      const match = matches.find(m => m.id === matchId);
      if(!match) return;
      const isRunning = match.gameData?.isTimerRunning || false;
      updateMatchGameData(matchId, { isTimerRunning: !isRunning });
  };

  const setGamePeriod = (matchId: string, period: MatchData['currentPeriod']) => {
      const match = matches.find(m => m.id === matchId);
      if(!match) return;

      // Smart Logic: Stop timer on HT or FT, Reset timer on new periods
      const shouldStop = period === 'HT' || period === 'FT';

      updateMatchGameData(matchId, { 
          currentPeriod: period, 
          isTimerRunning: false, 
          timer: 0 
      });
  };

  const handlePlayerGoal = (matchId: string, playerId: string, delta: number) => {
      const match = matches.find(m => m.id === matchId);
      if(!match) return;

      let newEvents = [...(match.gameData?.events || [])];

      if (delta > 0) {
          // Add Goal
          const minute = Math.ceil((match.gameData?.timer || 0) / 60);
          const newEvent: MatchEvent = {
              type: 'GOAL',
              minute,
              playerId: playerId
          };
          newEvents.push(newEvent);
      } else {
          // Remove Last Goal for this player
          // Find the last goal event index for this player
          // We iterate backwards
          let indexToRemove = -1;
          for (let i = newEvents.length - 1; i >= 0; i--) {
              if (newEvents[i].type === 'GOAL' && newEvents[i].playerId === playerId) {
                  indexToRemove = i;
                  break;
              }
          }
          if (indexToRemove !== -1) {
              newEvents.splice(indexToRemove, 1);
          }
      }

      updateMatchGameData(matchId, { events: newEvents });
  };

  const handleOpponentGoal = (matchId: string, action: 'ADD' | 'REMOVE') => {
      const match = matches.find(m => m.id === matchId);
      if(!match) return;

      const events = match.gameData?.events || [];

      if (action === 'ADD') {
          const minute = Math.ceil((match.gameData?.timer || 0) / 60);
          const newEvent: MatchEvent = {
              type: 'GOAL',
              minute,
              playerId: 'opponent' // Reserved ID for opponent
          };
          updateMatchGameData(matchId, { events: [...events, newEvent] });
      } else {
          // Remove last opponent goal
          // We need to find the last goal with playerId 'opponent'
          const oppGoals = events.filter(e => e.type === 'GOAL' && e.playerId === 'opponent');
          if (oppGoals.length > 0) {
              // Remove one instance
              const lastGoal = oppGoals[oppGoals.length - 1];
              // We can't identify easily without ID in event, but let's filter by index or reference
              // Simpler: filter out ONE opponent goal
              const indexToRemove = events.lastIndexOf(lastGoal);
              const newEvents = [...events];
              if (indexToRemove !== -1) newEvents.splice(indexToRemove, 1);
              updateMatchGameData(matchId, { events: newEvents });
          }
      }
  };

