                                                  <span className="text-5xl md:text-4xl font-mono font-bold text-emerald-400">
                                                      {matches.find(m => m.id === selectedMatchId)?.gameData?.events.filter(e => e.type === 'GOAL' && e.playerId !== 'opponent').length || 0}
                                                  </span>
