                             >
                                 Convocatória
                             </button>
                             <button 
                                onClick={() => setActiveGameTab('TACTICS')}
                                className={`px-3 py-1.5 rounded-lg text-sm font-medium transition whitespace-nowrap ${activeGameTab === 'TACTICS' ? 'bg-emerald-600 text-white' : 'text-slate-600 hover:bg-slate-200'}`}
                             >
                                 Titulares
                             </button>
