                                                          {isStarter ? 'Titular' : 'Banco'}
                                                      </span>
                                                   )}
                                               </div>
                                               <div className="text-xs text-slate-500">#{player.jerseyNumber} | {player.sportsDetails?.positions || 'S/ Pos'}</div>
