                                                         <button onClick={() => handleOpponentGoal(selectedMatchId!, 'REMOVE')} className="p-1 bg-slate-800 hover:bg-slate-700 border border-slate-700 rounded text-red-400 transition"><Minus className="w-3 h-3"/></button>
                                                     </div>
                                                  </div>
                                              </div>
                                          </div>
