                                      </div>

                                       {/* BENCH LIST */}
                                       <div className={`${mobileLiveTab === 'BENCH' ? 'flex' : 'hidden'} md:flex w-full md:w-1/3 bg-white rounded-xl border border-slate-200 overflow-hidden flex-col shadow-sm`}>
