                      </span>
                    </div>
                    <div className="text-sm mt-1 opacity-90">{session.time} - {session.description}</div>
                  </div>
                ))}
              </div>
            </div>

            {/* Attendance Sheet */}
            <div className="lg:col-span-2">
               {selectedSessionId ? (
                 <div className="bg-white rounded-xl shadow-sm border border-slate-200 h-full flex flex-col">
