                                                                    )}
                                                                </div>
                                                            </div>
                                                            <span className="font-mono font-bold text-slate-600 text-xl bg-slate-100 px-2 py-1 rounded">
                                                                {matches.find(m => m.id === selectedMatchId)?.gameData?.playerMinutes?.[p.id] || 0}'
