                  <div className="h-full flex flex-col items-center justify-center text-slate-400 border-2 border-dashed border-slate-200 rounded-xl bg-slate-50">
                    <Flag className="w-12 h-12 mb-2 opacity-50" />
                    <p>Selecione um jogo</p>
                 </div>
                )}
            </div>
        </div>
      )}

    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Player, Squad, Match } from '../types';
import { Save, X, Activity, User as UserIcon, BarChart3, Camera, Upload } from 'lucide-react';

interface PlayerFormProps {
  player?: Player | null; // null means new player
  squads: Squad[];
  matches?: Match[]; // Optional for new players
  onSave: (player: Player) => void;
  onCancel: () => void;
}

const PlayerForm: React.FC<PlayerFormProps> = ({ player, squads, matches = [], onSave, onCancel }) => {
  const [activeTab, setActiveTab] = useState<'INFO' | 'SPORTS' | 'STATS'>('INFO');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<Player>>({
    name: '',
    squadId: squads[0]?.id || '',
    address: '',
    birthDate: '',
    jerseyNumber: '',
    jerseyName: '',
    kitSize: 'M',
    tracksuitSize: 'M',
    notes: '',
    photoUrl: '',
    emergencyName: '',
    emergencyContact: '',
    sportsDetails: {
        technique: 50,
        speed: 50,
        tactical: 50,
        physical: 50,
        behavior: '',
        strongFoot: 'Direito',
        positions: ''
    }
  });

  useEffect(() => {
    if (player) {
      setFormData(player);
    }
  }, [player]);

  // Calculate Statistics
  const playerStats = useMemo(() => {
    if (!player) return null;

    let totalMatches = 0;
    let totalConvocations = 0;
    let totalStarts = 0;
    let totalBenchStarts = 0;
    let totalMinutes = 0;

    const matchHistory = matches
        .filter(m => m.convokedIds?.includes(player.id))
        .sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime())
        .map(m => {
            const minutes = m.gameData?.playerMinutes?.[player.id] || 0;
            const wasStarter = m.gameData?.startingXI 
                ? m.gameData.startingXI.includes(player.id)
                : m.gameData?.starters?.includes(player.id);

            return {
                id: m.id,
                date: m.date,
                opponent: m.opponent,
                minutes,
                wasStarter,
                wasBench: !wasStarter
            };
        });

    matchHistory.forEach(h => {
        totalConvocations++;
        if (h.wasStarter) totalStarts++;
        else totalBenchStarts++;
        totalMinutes += h.minutes;
        if (h.minutes > 0) totalMatches++;
    });

    return {
        totalMatches,
        totalConvocations,
        totalStarts,
        totalBenchStarts,
        totalMinutes,
        history: matchHistory
    };
  }, [player, matches]);


  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.squadId) {
      alert("Por favor preencha o nome e o escalão.");
      return;
    }

    const newPlayer: Player = {
      id: player?.id || crypto.randomUUID(),
      ...formData as Player,
      jerseyNumber: Number(formData.jerseyNumber)
    };
    onSave(newPlayer);
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
