    if (view === 'ADMIN' && user.role !== UserRole.ADMIN && user.username !== 'admin') return null;

    const isActive = currentView === view;
    return (
      <button
        onClick={() => {
          onNavigate(view);
          setIsMobileMenuOpen(false);
