                                     const dayOfWeek = matchDateObj.getDay(); // 0 (Sun) to 6 (Sat)
                                     // Calculate Monday of that week. If Sunday (0), go back 6 days. Else go back (day - 1).
                                     const diffToMonday = matchDateObj.getDate() - dayOfWeek + (dayOfWeek === 0 ? -6 : 1);

                                     const startOfWeek = new Date(matchDateObj);
