import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import PlayerForm from './components/PlayerForm';
import { 
  User, ViewState, Squad, Player, Match, 
  TrainingSession, AttendanceRecord, AttendanceStatus, 
  UserRole
} from './types';
import { storageService } from './services/storageService';
import { INITIAL_SQUADS, MOCK_USERS, MOCK_PLAYERS } from './constants';
import { Check, Plus, Trash2, Edit, ArrowLeft, Calendar, Loader2 } from 'lucide-react';

function App() {
  const [user, setUser] = useState<User | null>(null);
  const [view, setView] = useState<ViewState>('DASHBOARD');

  // Data State
  const [users, setUsers] = useState<User[]>([]);
  const [squads, setSquads] = useState<Squad[]>([]);
  const [players, setPlayers] = useState<Player[]>([]);
  const [matches, setMatches] = useState<Match[]>([]);
  const [sessions, setSessions] = useState<TrainingSession[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);

  // UI State
  const [selectedUserId, setSelectedUserId] = useState('');
  const [loginPassword, setLoginPassword] = useState('');
  const [selectedMatchId, setSelectedMatchId] = useState<string | null>(null);
  const [activeGameTab, setActiveGameTab] = useState<'DETAILS' | 'LINEUP' | 'LIVE'>('DETAILS');
  const [isPlayerFormOpen, setIsPlayerFormOpen] = useState(false);
  const [editingPlayer, setEditingPlayer] = useState<Player | null>(null);

  // Load Data
  useEffect(() => {
    const loadData = async () => {
      // Check for stored user
      const storedUser = storageService.getCurrentUser();
      if (storedUser) setUser(storedUser);

      // Load Users
      let loadedUsers = await storageService.getUsers();
      if (loadedUsers.length === 0) {
          // Fallback to Mocks if DB is empty and save them to seed DB
          loadedUsers = MOCK_USERS;
          await storageService.saveUsers(MOCK_USERS);
      }
      setUsers(loadedUsers);

      // Load other data
      const loadedSquads = await storageService.getSquads();
      setSquads(loadedSquads.length ? loadedSquads : INITIAL_SQUADS);

      const loadedPlayers = await storageService.getPlayers();
      setPlayers(loadedPlayers.length ? loadedPlayers : MOCK_PLAYERS);

      const loadedMatches = await storageService.getMatches();
      setMatches(loadedMatches);

      const loadedSessions = await storageService.getSessions();
      setSessions(loadedSessions);

      const loadedAttendance = await storageService.getAttendance();
      setAttendance(loadedAttendance);
    };
    loadData();
  }, []);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedUserId) {
        alert("Por favor selecione um utilizador.");
        return;
    }

    const found = users.find(u => u.id === selectedUserId);
    if (found && found.password === loginPassword) {
        setUser(found);
        storageService.persistLogin(found);
    } else {
        alert("Password incorreta.");
    }
  };

  const handleLogout = () => {
    setUser(null);
    storageService.logout();
    setSelectedUserId('');
    setLoginPassword('');
  };

  // Match Logic: Toggle Convocation
  const toggleConvocation = async (matchId: string, playerId: string) => {
      const match = matches.find(m => m.id === matchId);
      if (!match) return;

      const currentConvoked = match.convokedIds || [];
      let newConvoked;
      if (currentConvoked.includes(playerId)) {
          newConvoked = currentConvoked.filter(id => id !== playerId);
      } else {
          newConvoked = [...currentConvoked, playerId];
      }

      const updatedMatch = { ...match, convokedIds: newConvoked };
      setMatches(prev => prev.map(m => m.id === matchId ? updatedMatch : m));
      await storageService.saveMatches([updatedMatch]);
  };

  // Match Logic: Toggle Starter Status
  const toggleStarterStatus = async (matchId: string, playerId: string, e?: React.MouseEvent) => {
      e?.stopPropagation();
      const match = matches.find(m => m.id === matchId);
      if (!match) return;

      const gameData = match.gameData || { 
        starters: [], startingXI: [], substitutes: [], 
        formation: '4-3-3', events: [], playerMinutes: {}, 
        currentPeriod: 'PRE', timer: 0, isTimerRunning: false, 
        playerPositions: {} 
      };

      const starters = gameData.starters || [];
      let newStarters;
      if (starters.includes(playerId)) {
          newStarters = starters.filter(id => id !== playerId);
      } else {
          newStarters = [...starters, playerId];
      }

      const updatedMatch = {
          ...match,
          gameData: { ...gameData, starters: newStarters }
      };

      setMatches(prev => prev.map(m => m.id === matchId ? updatedMatch : m));
      await storageService.saveMatches([updatedMatch]);
  };

  if (!user) {
      return (
          <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
              <form onSubmit={handleLogin} className="bg-white p-8 rounded-lg shadow-xl w-full max-w-md">
                  <div className="text-center mb-8">
                      <h1 className="text-2xl font-bold text-slate-800">CDN Team Manager</h1>
                      <p className="text-slate-500 text-sm">Área Reservada</p>
                  </div>

                  <div className="space-y-4">
                      <div>
                          <label className="block text-sm font-medium text-slate-700 mb-1">Selecionar Utilizador</label>
                          <select 
                            className="w-full p-3 border border-slate-300 rounded-lg bg-white text-slate-800 focus:ring-2 focus:ring-emerald-500 outline-none" 
                            value={selectedUserId} 
                            onChange={e => setSelectedUserId(e.target.value)}
                          >
                            <option value="">Selecione...</option>
                            {users.map(u => (
                                <option key={u.id} value={u.id}>
                                    {u.name} ({u.role})
                                </option>
                            ))}
                          </select>
                      </div>

                      <div>
                          <label className="block text-sm font-medium text-slate-700 mb-1">Password</label>
                          <input 
                            className="w-full p-3 border border-slate-300 rounded-lg text-slate-800 focus:ring-2 focus:ring-emerald-500 outline-none" 
                            type="password" 
                            placeholder="Sua password" 
                            value={loginPassword} 
                            onChange={e => setLoginPassword(e.target.value)} 
                          />
                      </div>

                      <button type="submit" className="w-full bg-emerald-600 text-white font-bold p-3 rounded-lg hover:bg-emerald-700 transition shadow-md mt-2">
                          Entrar
                      </button>
                  </div>
              </form>
          </div>
      );
  }

  return (
    <Layout user={user} currentView={view} onNavigate={setView} onLogout={handleLogout}>
       {/* PLAYERS VIEW */}
       {view === 'PLAYERS' && (
           <div>
               <div className="flex justify-between items-center mb-6">
                   <h2 className="text-2xl font-bold text-slate-800">Atletas</h2>
                   <button onClick={() => { setEditingPlayer(null); setIsPlayerFormOpen(true); }} className="flex items-center bg-emerald-600 text-white px-4 py-2 rounded shadow-sm hover:bg-emerald-700 transition">
                       <Plus className="w-4 h-4 mr-2" /> Novo Atleta
                   </button>
               </div>

               {isPlayerFormOpen ? (
                   <PlayerForm 
                      player={editingPlayer} 
                      squads={squads} 
                      matches={matches} 
                      onSave={async (p) => {
                          const newPlayers = editingPlayer 
                             ? players.map(pl => pl.id === p.id ? p : pl)
                             : [...players, p];
                          setPlayers(newPlayers);
                          await storageService.savePlayers([p]);
                          setIsPlayerFormOpen(false);
                      }} 
                      onCancel={() => setIsPlayerFormOpen(false)} 
                    />
               ) : (
                   <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                       {players.map(p => (
                           <div key={p.id} className="bg-white p-4 rounded-lg shadow-sm border border-slate-200 flex justify-between items-center group hover:border-emerald-300 transition">
                               <div className="flex items-center">
                                   <div className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center font-bold text-slate-600 mr-3">
                                       {p.jerseyNumber}
                                   </div>
                                   <div>
                                       <p className="font-bold text-slate-800">{p.name}</p>
                                       <p className="text-xs text-slate-500 font-medium bg-slate-100 px-2 py-0.5 rounded-full inline-block mt-1">
                                           {squads.find(s => s.id === p.squadId)?.name}
                                       </p>
                                   </div>
                               </div>
                               <button onClick={() => { setEditingPlayer(p); setIsPlayerFormOpen(true); }} className="p-2 text-slate-400 hover:text-emerald-600 hover:bg-emerald-50 rounded-full transition">
                                   <Edit className="w-4 h-4" />
                               </button>
                           </div>
                       ))}
                   </div>
               )}
           </div>
       )}

       {/* MATCHES VIEW */}
       {view === 'MATCHES' && (
           <div>
               {!selectedMatchId ? (
                   <div>
                        <div className="flex justify-between items-center mb-6">
                            <h2 className="text-2xl font-bold text-slate-800">Jogos</h2>
                            <button className="flex items-center bg-emerald-600 text-white px-4 py-2 rounded shadow-sm hover:bg-emerald-700 transition">
                                <Plus className="w-4 h-4 mr-2" /> Agendar Jogo
                            </button>
                        </div>
                        <div className="grid gap-4">
                            {matches.map(m => (
                                <div key={m.id} onClick={() => setSelectedMatchId(m.id)} className="bg-white p-4 rounded-lg shadow-sm border border-slate-200 cursor-pointer hover:border-emerald-500 hover:shadow-md transition group">
                                    <div className="flex justify-between items-center mb-2">
                                        <span className="font-bold text-lg text-slate-800">{m.opponent}</span>
                                        <span className="text-xs bg-slate-100 text-slate-600 px-2 py-1 rounded border border-slate-200">{m.date}</span>
                                    </div>
                                    <div className="flex justify-between items-center">
                                        <p className="text-sm text-emerald-600 font-medium">{squads.find(s => s.id === m.squadId)?.name}</p>
                                        <span className="text-xs text-slate-400 group-hover:text-emerald-500 transition">Ver Detalhes →</span>
                                    </div>
                                </div>
                            ))}
                            {matches.length === 0 && (
                                <div className="text-center py-10 bg-white rounded-lg border border-dashed border-slate-300">
                                    <p className="text-slate-500">Sem jogos agendados.</p>
                                </div>
                            )}
                        </div>
                   </div>
               ) : (
                   <div>
                       <button onClick={() => setSelectedMatchId(null)} className="mb-4 flex items-center text-slate-500 hover:text-slate-800 transition">
                           <ArrowLeft className="w-4 h-4 mr-2" /> Voltar à lista
                       </button>

                       <div className="bg-white rounded-lg shadow-sm border border-slate-200 overflow-hidden">
                           <div className="flex border-b border-slate-100 bg-slate-50">
                               <button 
                                 className={`flex-1 py-3 text-sm font-medium transition ${activeGameTab === 'DETAILS' ? 'border-b-2 border-emerald-500 text-emerald-600 bg-white' : 'text-slate-500 hover:text-slate-700'}`}
                                 onClick={() => setActiveGameTab('DETAILS')}
                               >Detalhes</button>
                               <button 
                                 className={`flex-1 py-3 text-sm font-medium transition ${activeGameTab === 'LINEUP' ? 'border-b-2 border-emerald-500 text-emerald-600 bg-white' : 'text-slate-500 hover:text-slate-700'}`}
                                 onClick={() => setActiveGameTab('LINEUP')}
                               >Convocatória</button>
                               <button 
                                 className={`flex-1 py-3 text-sm font-medium transition ${activeGameTab === 'LIVE' ? 'border-b-2 border-emerald-500 text-emerald-600 bg-white' : 'text-slate-500 hover:text-slate-700'}`}
                                 onClick={() => setActiveGameTab('LIVE')}
                               >Ao Vivo</button>
                           </div>

                           <div className="p-4">
                               {/* CONVOCATORIA TAB */}
                               {activeGameTab === 'LINEUP' && (
                                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                                    {players
                                       .filter(p => p.squadId === matches.find(m => m.id === selectedMatchId)?.squadId)
                                       .map(player => {
                                         const match = matches.find(m => m.id === selectedMatchId);
                                         if (!match) return null;

                                         const isSelected = match.convokedIds?.includes(player.id);
                                         const isStarter = match.gameData?.starters?.includes(player.id);

                                         // --- Weekly Stats Calculation ---
                                         const matchDateObj = new Date(match.date);
                                         const dayOfWeek = matchDateObj.getDay(); 
                                         const diffToMonday = matchDateObj.getDate() - dayOfWeek + (dayOfWeek === 0 ? -6 : 1);

                                         const startOfWeek = new Date(matchDateObj);
                                         startOfWeek.setDate(diffToMonday);
                                         startOfWeek.setHours(0, 0, 0, 0);

                                         const endOfWeek = new Date(startOfWeek);
                                         endOfWeek.setDate(startOfWeek.getDate() + 6);
                                         endOfWeek.setHours(23, 59, 59, 999);

                                         const weeklySessionIds = sessions.filter(s => {
                                             const sDate = new Date(s.date);
                                             return s.squadId === match.squadId && sDate >= startOfWeek && sDate <= endOfWeek;
                                         }).map(s => s.id);

                                         const weeklyAbsences = attendance.filter(a => 
                                            weeklySessionIds.includes(a.sessionId) && 
                                            a.playerId === player.id && 
                                            a.status === AttendanceStatus.ABSENT
                                         ).length;

                                         const weeklyLates = attendance.filter(a => 
                                            weeklySessionIds.includes(a.sessionId) && 
                                            a.playerId === player.id && 
                                            a.status === AttendanceStatus.LATE
                                         ).length;

                                         return (
                                           <div 
                                             key={player.id} 
                                             onClick={() => toggleConvocation(selectedMatchId, player.id)}
                                             className={`flex flex-col p-3 rounded-lg border cursor-pointer transition relative group ${
                                               isSelected 
                                                 ? 'bg-emerald-50 border-emerald-500 ring-1 ring-emerald-500' 
                                                 : 'bg-white border-slate-200 hover:border-emerald-200'
                                             }`}
                                           >
                                              <div className="flex items-center">
                                                <div className={`w-5 h-5 rounded border mr-3 flex items-center justify-center transition-colors ${isSelected ? 'bg-emerald-600 border-emerald-600' : 'border-slate-300'}`}>
                                                   {isSelected && <Check className="w-3 h-3 text-white" />}
                                                </div>
                                                <div className="flex-1">
                                                   <div className="text-sm font-medium text-slate-800 flex flex-wrap justify-between items-center gap-1">
                                                       <span className="mr-1">{player.name}</span>

                                                       <div className="flex items-center gap-1">
                                                           {(weeklyAbsences > 0 || weeklyLates > 0) ? (
                                                               <>
                                                                {weeklyAbsences > 0 && (
                                                                    <span className="text-[9px] font-bold px-1.5 py-0.5 rounded bg-red-100 text-red-700 border border-red-200" title="Faltas nesta semana">
                                                                        {weeklyAbsences}F
                                                                    </span>
                                                                )}
                                                                {weeklyLates > 0 && (
                                                                    <span className="text-[9px] font-bold px-1.5 py-0.5 rounded bg-yellow-100 text-yellow-700 border border-yellow-200" title="Atrasos nesta semana">
                                                                        {weeklyLates}A
                                                                    </span>
                                                                )}
                                                               </>
                                                           ) : (
                                                               <span className="text-[9px] font-bold px-1.5 py-0.5 rounded bg-slate-100 text-slate-400 border border-slate-200 opacity-60" title="Assiduidade Perfeita na Semana">
                                                                   100%
                                                               </span>
                                                           )}

                                                           {isSelected && (
                                                              <span className={`text-[10px] px-2 py-0.5 rounded-full font-semibold ${isStarter ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-200 text-slate-600'}`}>
                                                                  {isStarter ? 'Titular' : 'Banco'}
                                                              </span>
                                                           )}
                                                       </div>
                                                   </div>
                                                   <div className="text-xs text-slate-500 mt-0.5">#{player.jerseyNumber} | {player.sportsDetails?.positions || 'S/ Pos'}</div>
                                                </div>
                                              </div>

                                              {isSelected && (
                                                  <div className="mt-2 pt-2 border-t border-emerald-100 flex gap-2">
                                                      <button 
                                                        onClick={(e) => toggleStarterStatus(selectedMatchId, player.id, e)}
                                                        className={`flex-1 text-xs py-1.5 rounded text-center transition font-medium ${isStarter ? 'bg-white border border-slate-200 text-slate-600 hover:bg-slate-50' : 'bg-emerald-600 text-white hover:bg-emerald-700'}`}
                                                      >
                                                          {isStarter ? 'Mover p/ Banco' : 'Definir Titular'}
                                                      </button>
                                                  </div>
                                              )}
                                           </div>
                                         )
                                       })}
                                 </div>
                               )}

                               {activeGameTab === 'DETAILS' && (
                                   <div className="flex flex-col items-center justify-center py-10 text-slate-500">
                                       <Calendar className="w-12 h-12 mb-4 text-slate-300" />
                                       <p>Selecione a aba <b>Convocatória</b> para definir os jogadores.</p>
                                   </div>
                               )}

                               {activeGameTab === 'LIVE' && (
                                   <div className="flex flex-col items-center justify-center py-10 text-slate-500">
                                       <Loader2 className="w-12 h-12 mb-4 text-slate-300 animate-spin-slow" />
                                       <p>Modo Jogo ao Vivo - Brevemente</p>
                                   </div>
                               )}
                           </div>
                       </div>
                   </div>
               )}
           </div>
       )}

       {/* DASHBOARD VIEW */}
       {view === 'DASHBOARD' && (
           <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="bg-white p-6 rounded-lg shadow-sm border border-slate-200">
                    <h3 className="text-slate-500 font-bold uppercase text-xs tracking-wider">Total Atletas</h3>
                    <p className="text-3xl font-bold text-emerald-600 mt-2">{players.length}</p>
