                <div className="bg-white p-6 rounded-lg shadow-sm border border-slate-200">
                    <h3 className="text-slate-500 font-bold uppercase text-xs tracking-wider">Treinos</h3>
                    <p className="text-3xl font-bold text-purple-600 mt-2">{sessions.length}</p>
                </div>
           </div>
       )}

       {/* TRAINING VIEW */}
       {view === 'TRAINING' && (
           <div className="text-center p-10 text-slate-500 bg-white rounded-lg border border-dashed border-slate-300">
               <Calendar className="w-12 h-12 mx-auto mb-4 opacity-50" />
               <h2 className="text-xl font-medium">Gestão de Treinos</h2>
               <p className="mt-2 text-sm">Funcionalidade simplificada para esta demonstração.</p>
           </div>
       )}

       {/* ADMIN VIEW */}
       {view === 'ADMIN' && (
           <div className="text-center p-10 text-slate-500 bg-white rounded-lg border border-dashed border-slate-300">
               <h2 className="text-xl font-medium">Administração</h2>
               <p className="mt-2 text-sm">Funcionalidade simplificada para esta demonstração.</p>
           </div>
       )}
    </Layout>
  );
}

