  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const found = MOCK_USERS.find(u => u.username === username && u.password === password);
    if (found) {
      setUser(found);
      storageService.persistLogin(found);
      setView('DASHBOARD');
    } else {
      alert("Credenciais inválidas");
    }
  };

  const handleLogout = () => {
    setUser(null);
    storageService.logout();
  };

  // Match Logic
  const handlePlayerGoal = async (matchId: string, playerId: string, delta: number) => {
    const match = matches.find(m => m.id === matchId);
    if (!match || !match.gameData) return;

    const newEvents = [...match.gameData.events];
    if (delta > 0) {
      newEvents.push({
        type: 'GOAL',
        minute: Math.floor(match.gameData.timer / 60), // Simplified timer
        playerId
      });
    } else {
      // Remove last goal for this player
      const idx = newEvents.reverse().findIndex(e => e.type === 'GOAL' && e.playerId === playerId);
      if (idx !== -1) {
        newEvents.splice(idx, 1);
      }
      newEvents.reverse();
    }

    const updatedMatch = {
      ...match,
      gameData: {
        ...match.gameData,
        events: newEvents
      }
    };

    const updatedMatches = matches.map(m => m.id === matchId ? updatedMatch : m);
    setMatches(updatedMatches);
    await storageService.saveMatches(updatedMatches);
  };

  const handleSubstitution = async (matchId: string | null, playerOutId: string, playerInId: string) => {
    if(!matchId) return;
    const match = matches.find(m => m.id === matchId);
    if (!match || !match.gameData) return;

    const newStarters = match.gameData.starters.filter(id => id !== playerOutId);
    newStarters.push(playerInId);

    const newEvents = [...match.gameData.events];
    newEvents.push({
      type: 'SUBSTITUTION',
      minute: Math.floor(match.gameData.timer / 60),
      playerId: playerInId,
      playerOutId: playerOutId
    });

    const updatedMatch = {
      ...match,
      gameData: {
        ...match.gameData,
        starters: newStarters,
        events: newEvents
      }
    };

    const updatedMatches = matches.map(m => m.id === matchId ? updatedMatch : m);
    setMatches(updatedMatches);
    await storageService.saveMatches(updatedMatches);
  };

  const initializeMatch = async (match: Match) => {
      // Setup initial game data
      const newMatch: Match = {
          ...match,
          gameData: {
              starters: match.convokedIds.slice(0, 7), // Mock starting 7
              startingXI: match.convokedIds.slice(0, 7),
              substitutes: match.convokedIds.slice(7),
              formation: '3-2-1 (F7)',
              events: [],
              playerMinutes: {},
              currentPeriod: '1H',
              timer: 0,
              isTimerRunning: true,
              playerPositions: {}
          }
      };
      const updated = matches.map(m => m.id === match.id ? newMatch : m);
      setMatches(updated);
      await storageService.saveMatches(updated);
      setSelectedMatchId(match.id);
  };

  if (!user) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
        <div className="bg-white rounded-xl shadow-2xl p-8 w-full max-w-md">
          <div className="text-center mb-8">
            <h1 className="text-2xl font-bold text-slate-800">Gestão Desportiva</h1>
            <p className="text-slate-500">Inicie sessão para continuar</p>
          </div>
          <form onSubmit={handleLogin} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Utilizador</label>
              <div className="relative">
                <LogIn className="absolute left-3 top-2.5 h-5 w-5 text-slate-400" />
                <input 
                  type="text" 
                  value={username} 
                  onChange={e => setUsername(e.target.value)}
                  className="pl-10 w-full p-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-emerald-500"
                  placeholder="admin"
                />
              </div>
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Password</label>
              <div className="relative">
                <Lock className="absolute left-3 top-2.5 h-5 w-5 text-slate-400" />
                <input 
                  type="password" 
                  value={password} 
                  onChange={e => setPassword(e.target.value)}
                  className="pl-10 w-full p-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-emerald-500"
                  placeholder="***"
                />
              </div>
            </div>
            <button type="submit" className="w-full bg-emerald-600 text-white py-2 rounded-lg hover:bg-emerald-700 transition">
              Entrar
            </button>
          </form>
        </div>
      </div>
    );
  }

  // Helper to get logic for views (Simplified for this file)
  const renderDashboard = () => (
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
              <div className="flex items-center justify-between">
                  <div>
                      <p className="text-sm font-medium text-slate-500">Total Atletas</p>
                      <h3 className="text-2xl font-bold text-slate-800">{players.length}</h3>
                  </div>
                  <div className="p-3 bg-emerald-100 rounded-full">
                      <Users className="w-6 h-6 text-emerald-600" />
                  </div>
              </div>
          </div>
          {/* Add more cards */}
      </div>
  );

  const renderPlayers = () => (
      <div className="h-full flex flex-col">
          <div className="flex justify-between items-center mb-6">
              <h2 className="text-2xl font-bold text-slate-800">Atletas</h2>
              <button 
                onClick={() => { setEditingPlayer(null); setIsPlayerFormOpen(true); }}
                className="flex items-center px-4 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700"
              >
                  <Plus className="w-4 h-4 mr-2" /> Novo Atleta
              </button>
          </div>

          {isPlayerFormOpen ? (
              <PlayerForm 
                player={editingPlayer} 
                squads={squads} 
                matches={matches}
                onSave={async (p) => {
                    const newPlayers = editingPlayer 
                        ? players.map(pl => pl.id === p.id ? p : pl) 
                        : [...players, p];
                    setPlayers(newPlayers);
                    await storageService.savePlayers(newPlayers);
                    setIsPlayerFormOpen(false);
                }} 
                onCancel={() => setIsPlayerFormOpen(false)} 
              />
          ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 overflow-y-auto pb-20">
                  {players.map(p => (
                      <div key={p.id} className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex items-center justify-between">
                          <div className="flex items-center space-x-4">
                              <div className="w-12 h-12 rounded-full bg-slate-100 flex items-center justify-center font-bold text-slate-500">
                                  {p.photoUrl ? <img src={p.photoUrl} className="w-full h-full rounded-full object-cover"/> : p.jerseyNumber}
                              </div>
                              <div>
                                  <h3 className="font-bold text-slate-800">{p.name}</h3>
                                  <p className="text-sm text-slate-500">{squads.find(s=>s.id===p.squadId)?.name}</p>
                              </div>
                          </div>
                          <button onClick={() => { setEditingPlayer(p); setIsPlayerFormOpen(true); }} className="text-slate-400 hover:text-emerald-600">
                              <Edit className="w-5 h-5" />
                          </button>
                      </div>
                  ))}
              </div>
          )}
      </div>
  );

  const renderTraining = () => (
      <div className="h-full flex flex-col items-center justify-center text-slate-400">
          <Calendar className="w-16 h-16 mb-4 opacity-50" />
          <p>Módulo de Treinos (Simplificado)</p>
          {/* Gemini integration could go here */}
      </div>
  );

  const renderMatchList = () => (
    <div className="space-y-4">
        <div className="flex justify-between items-center mb-6">
              <h2 className="text-2xl font-bold text-slate-800">Jogos</h2>
              <button 
                onClick={() => { 
                    // Create mock match
                    const newMatch: Match = {
                        id: crypto.randomUUID(),
                        squadId: squads[0]?.id || '',
                        date: new Date().toISOString().split('T')[0],
                        time: '15:00',
                        opponent: 'Adversário ' + (matches.length + 1),
                        location: 'Casa',
                        convokedIds: players.slice(0, 10).map(p => p.id)
                    };
                    const newMatches = [...matches, newMatch];
                    setMatches(newMatches);
                    storageService.saveMatches(newMatches);
                }}
                className="flex items-center px-4 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700"
              >
                  <Plus className="w-4 h-4 mr-2" /> Novo Jogo
              </button>
        </div>
        <div className="grid gap-4">
            {matches.map(m => (
                <div key={m.id} className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex justify-between items-center">
                    <div>
                        <h3 className="font-bold text-lg text-slate-800">{m.opponent}</h3>
                        <p className="text-sm text-slate-500">{m.date} | {m.location}</p>
                    </div>
                    <div className="flex gap-2">
                        <button 
                            onClick={() => initializeMatch(m)}
                            className="px-3 py-1 bg-slate-800 text-white rounded text-sm flex items-center"
                        >
                            <Play className="w-4 h-4 mr-2"/> Iniciar / Live
                        </button>
                    </div>
                </div>
            ))}
        </div>
    </div>
  );

  const renderLiveMatch = () => {
      // Logic for live match tabs (Mobile)

      return (
          <div className="flex flex-col h-full">
              <div className="flex items-center justify-between mb-4">
                  <button onClick={() => setSelectedMatchId(null)} className="text-slate-500 hover:text-slate-800 flex items-center">
                      <ChevronLeft className="w-5 h-5 mr-1" /> Voltar
                  </button>
                  <div className="flex gap-2">
                      <button 
                        onClick={() => setMobileLiveTab('FIELD')} 
                        className={`md:hidden px-3 py-1 rounded text-sm font-bold ${mobileLiveTab === 'FIELD' ? 'bg-emerald-600 text-white' : 'bg-slate-200 text-slate-600'}`}
                      >
                          Campo
                      </button>
                      <button 
                        onClick={() => setMobileLiveTab('BENCH')} 
                        className={`md:hidden px-3 py-1 rounded text-sm font-bold ${mobileLiveTab === 'BENCH' ? 'bg-emerald-600 text-white' : 'bg-slate-200 text-slate-600'}`}
                      >
                          Banco
                      </button>
                  </div>
              </div>

              {/* Inserted Snippet Content Logic */}
              <div className="flex-1 overflow-hidden flex flex-col md:flex-row gap-4 px-2 md:px-0 pb-2">

                  {/* FIELD PLAYERS LIST */}
                  <div className={`${mobileLiveTab === 'FIELD' ? 'flex' : 'hidden'} md:flex flex-1 bg-white rounded-xl border border-slate-200 overflow-hidden flex-col shadow-sm`}>
                      <div className="p-3 border-b border-slate-100 bg-emerald-50 text-emerald-800 font-bold text-sm flex justify-between shrink-0 items-center">
                          <span className="flex items-center"><Shirt className="w-4 h-4 mr-2"/> JOGADORES EM CAMPO</span>
                          <span className="hidden md:inline text-xs font-normal bg-emerald-100 px-2 py-0.5 rounded text-emerald-700">Tempo de Jogo</span>
                      </div>
                      <div className="overflow-y-auto flex-1 p-2 space-y-2 bg-slate-50/50">
                          {players
                            .filter(p => matches.find(m => m.id === selectedMatchId)?.gameData?.starters?.includes(p.id))
                            .map(p => {
                                const goals = matches.find(m => m.id === selectedMatchId)?.gameData?.events?.filter(e => e.type === 'GOAL' && e.playerId === p.id).length || 0;
                                const minutes = matches.find(m => m.id === selectedMatchId)?.gameData?.playerMinutes?.[p.id] || 0;

                                return (
                                <div key={p.id} className="flex flex-col border border-slate-200 rounded-xl bg-white shadow-sm p-3 gap-3 relative overflow-hidden">
                                    {/* Top Row: Info & BIG MINUTES */}
                                    <div className="flex justify-between items-start">
                                        <div className="flex items-center gap-3">
                                            <span className="w-10 h-10 md:w-8 md:h-8 rounded-full bg-slate-800 text-white flex items-center justify-center font-bold shadow-md text-lg md:text-sm border-2 border-white ring-1 ring-slate-200">
                                                {p.jerseyNumber}
                                            </span>
                                            <div>
                                                <div className="font-bold text-slate-800 text-lg md:text-base leading-tight">{p.name}</div>
                                                {goals > 0 && (
                                                    <div className="flex items-center text-xs text-yellow-600 font-bold mt-1 bg-yellow-50 px-2 py-0.5 rounded-full w-fit">
                                                        <Trophy className="w-3 h-3 mr-1 fill-yellow-500" /> {goals} {goals === 1 ? 'Golo' : 'Golos'}
                                                    </div>
                                                )}
                                            </div>
                                        </div>

                                        {/* Optimized Minutes Display */}
                                        <div className="flex flex-col items-end pl-2">
                                            <span className="text-[10px] text-slate-400 font-bold uppercase tracking-wider mb-0.5">Minutos</span>
                                            <span className="font-mono font-bold text-3xl md:text-xl text-emerald-600 leading-none tracking-tight">
                                                {minutes}'
                                            </span>
                                        </div>
                                    </div>

                                    {/* Bottom Row: Actions */}
                                    <div className="flex items-center gap-2 pt-2 border-t border-slate-100 mt-1">
                                        {/* Goal Controls */}
                                        <div className="flex items-center bg-slate-50 rounded-lg border border-slate-200 flex-1 justify-between px-1 h-10">
                                            <button 
                                                onClick={() => selectedMatchId && handlePlayerGoal(selectedMatchId, p.id, -1)}
                                                disabled={goals === 0}
                                                className={`w-10 h-full flex items-center justify-center rounded hover:bg-slate-200 active:bg-slate-300 transition ${goals === 0 ? 'text-slate-300' : 'text-slate-600'}`}
                                            >
                                                <Minus className="w-5 h-5" />
                                            </button>
                                            <span className="font-bold text-slate-800 text-lg w-6 text-center">{goals}</span>
                                            <button 
                                                onClick={() => selectedMatchId && handlePlayerGoal(selectedMatchId, p.id, 1)}
                                                className="w-10 h-full flex items-center justify-center text-emerald-600 hover:bg-emerald-50 active:bg-emerald-100 rounded transition"
                                            >
                                                <Plus className="w-5 h-5" />
                                            </button>
                                        </div>

                                        {/* Sub Out - Optimized for Touch */}
                                        <div className="relative flex-1 h-10">
                                            <div className="bg-white text-red-600 border border-red-200 rounded-lg flex items-center justify-center font-bold h-full text-sm cursor-pointer hover:bg-red-50 transition shadow-sm">
                                                <ArrowRightLeft className="w-4 h-4 mr-2" /> SUBSTITUIR
                                            </div>
                                            <select 
                                                className="absolute inset-0 opacity-0 w-full h-full cursor-pointer"
                                                onChange={(e) => {
                                                    if (e.target.value && selectedMatchId) {
                                                        handleSubstitution(selectedMatchId, p.id, e.target.value);
                                                        e.target.value = '';
                                                    }
                                                }}
                                                defaultValue=""
                                            >
                                                <option value="" disabled>Substituir por...</option>
                                                {players
                                                    .filter(sub => matches.find(m => m.id === selectedMatchId)?.convokedIds?.includes(sub.id))
                                                    .filter(sub => !matches.find(m => m.id === selectedMatchId)?.gameData?.starters?.includes(sub.id))
                                                    .map(sub => (
                                                        <option key={sub.id} value={sub.id}>Entra: #{sub.jerseyNumber} {sub.name}</option>
                                                    ))
                                                }
                                            </select>
                                        </div>
                                    </div>
                                </div>
                            )})}
                            {players.filter(p => matches.find(m => m.id === selectedMatchId)?.gameData?.starters?.includes(p.id)).length === 0 && (
                                <div className="flex flex-col items-center justify-center h-40 text-slate-400 italic bg-white rounded-xl border border-dashed border-slate-200">
                                    <Shirt className="w-8 h-8 mb-2 opacity-50"/>
                                    <span>Nenhum jogador em campo.</span>
                                </div>
                            )}
                      </div>
                  </div>

                    {/* BENCH LIST */}
                    <div className={`${mobileLiveTab === 'BENCH' ? 'flex' : 'hidden'} md:flex w-full md:w-1/3 bg-white rounded-xl border border-slate-200 overflow-hidden flex-col shadow-sm`}>
                      <div className="p-3 border-b border-slate-100 bg-slate-50 text-slate-600 font-bold text-sm flex justify-between items-center shrink-0">
                          <span className="flex items-center"><UserCheck className="w-4 h-4 mr-2"/> BANCO DE SUPLENTES</span>
                          <span className="bg-slate-200 px-2 py-0.5 rounded-full text-[10px] text-slate-600 font-bold">
                            {players.filter(p => matches.find(m => m.id === selectedMatchId)?.convokedIds?.includes(p.id))
                            .filter(p => !matches.find(m => m.id === selectedMatchId)?.gameData?.starters?.includes(p.id)).length}
                          </span>
                      </div>
                      <div className="overflow-y-auto p-2 space-y-2 bg-slate-50/50">
                          {players
                            .filter(p => matches.find(m => m.id === selectedMatchId)?.convokedIds?.includes(p.id))
                            .filter(p => !matches.find(m => m.id === selectedMatchId)?.gameData?.starters?.includes(p.id))
                            .map(p => (
                                <div key={p.id} className="flex justify-between bg-white border border-slate-200 rounded-xl items-center p-3 shadow-sm hover:border-emerald-300 transition-colors">
                                    <div className="flex items-center gap-3">
                                        <span className="w-9 h-9 rounded-full bg-slate-100 text-slate-600 flex items-center justify-center font-bold text-sm border border-slate-200">
                                            {p.jerseyNumber}
                                        </span>
                                        <span className="text-slate-800 font-medium text-base">
                                            {p.name}
                                        </span>
                                    </div>

                                    {/* Quick Sub IN Logic */}
                                    <div className="relative">
                                          <div className="bg-emerald-600 text-white shadow-md rounded-lg flex items-center justify-center font-bold px-4 py-2 text-xs cursor-pointer hover:bg-emerald-700 active:scale-95 transition">
                                            <ArrowRightLeft className="w-3 h-3 mr-1.5" /> ENTRAR
                                          </div>
                                        <select 
                                            className="absolute inset-0 opacity-0 w-full h-full cursor-pointer"
                                            onChange={(e) => {
                                                if (e.target.value) {
                                                    handleSubstitution(selectedMatchId, e.target.value, p.id); 
                                                    e.target.value = ''; 
                                                }
                                            }}
                                            defaultValue=""
                                        >
                                            <option value="" disabled>Substituir quem...</option>
                                            {matches.find(m => m.id === selectedMatchId)?.gameData?.starters?.map(starterId => {
                                                const starter = players.find(sp => sp.id === starterId);
                                                return <option key={starterId} value={starterId}>Sai: #{starter?.jerseyNumber} {starter?.name}</option>
                                            })}
                                        </select>
                                    </div>
                                </div>
                            ))}
                            {players.filter(p => matches.find(m => m.id === selectedMatchId)?.convokedIds?.includes(p.id) && !matches.find(m => m.id === selectedMatchId)?.gameData?.starters?.includes(p.id)).length === 0 && (
                                  <div className="flex flex-col items-center justify-center h-40 text-slate-400 italic bg-white rounded-xl border border-dashed border-slate-200">
                                    <UserCheck className="w-8 h-8 mb-2 opacity-50"/>
                                    <span>Banco vazio.</span>
                                </div>
                            )}
                      </div>
                    </div>
              </div>
          </div>
      );
  };

  return (
    <Layout user={user} currentView={view} onNavigate={setView} onLogout={handleLogout}>
      {view === 'DASHBOARD' && renderDashboard()}
      {view === 'PLAYERS' && renderPlayers()}
      {view === 'TRAINING' && renderTraining()}
      {view === 'MATCHES' && (selectedMatchId ? renderLiveMatch() : renderMatchList())}
      {view === 'ADMIN' && <div className="text-center text-slate-400 mt-20">Área de Administração (Em construção)</div>}
    </Layout>
  );
}

export default App;
